/* Auto-generated by tools/build_cards.py — pipeline artifact. Do not hand-edit */
window.CARDS={"asof":"2026-09-29","areas":[{"area":"I","title":"Ethics, Professional Responsibilities and Federal Tax Procedures","key":"reg_area1_ethics_procedures","n":11},{"area":"II","title":"Business Law","key":"reg_area2_business_law","n":13},{"area":"III","title":"Federal Taxation of Property Transactions","key":"reg_area3_property","n":4},{"area":"IV","title":"Federal Taxation of Individuals","key":"reg_area4_individuals","n":12},{"area":"V","title":"Federal Taxation of Entities","key":"reg_area5_entities","n":17}],"cards":[{"id":"CARD-REG-I-A-01","area":"I","group":"A","topic":"Regulations governing practice before the IRS (Circular 230)","title":"IRS practice rights and representation forms","rules":["Unlimited practice: attorney + CPA + enrolled agent, none suspended or disbarred (31 CFR §10.3(a)-(c))","Enrolled actuary → listed pension-plan issues only; enrolled retirement plan agent → listed plan programs only","Form 2848 → authority to represent; Form 8821 → inspect and receive tax information only","Unenrolled preparer with AFSP Record of Completion → represent only at examination of returns the preparer signed","§10.7(c) no-enrollment cases: self, immediate family, employer full-time employee, partnership general partner, corporate officer","PTIN holder without credential or Record of Completion → prepare returns only; no representation"],"steps":["Credential check: attorney / CPA / enrolled agent → unlimited practice","Actuary or retirement plan agent → confirm the issue is on the listed subjects","Preparer only → Record of Completion + signed the return + examination level only","No credential → test §10.7(c) list (self, family, employer, partnership, officer)","No match → prepare and sign only; representation refused"],"traps":["Form 8821 treated as authority to represent; only Form 2848 (power of attorney) authorizes representation","Any PTIN holder or unrelated friend assumed able to appear at examination; no credential + no Record of Completion → no representation"],"ex":{"q":"Kim, a paid preparer with a PTIN but no credential and no AFSP Record of Completion, prepared and signed a client's 2025 return. IRS selects it for examination. May Kim represent the client, and which form applies if the client only wants Kim to receive IRS notices?","a":"No representation. Only an attorney, CPA or enrolled agent (or a Record of Completion holder, limited) may represent. Receipt of information only → Form 8821.","work":["Credential? none → not attorney/CPA/EA","Record of Completion? none → no limited rights","§10.7(c) list? unrelated client → no exception","Information-only access → Form 8821, representation → Form 2848"]},"cites":[{"l":"31 CFR §10.3 Who may practice","u":"https://www.ecfr.gov/current/title-31/section-10.3"},{"l":"31 CFR §10.7 Limited practice","u":"https://www.ecfr.gov/current/title-31/section-10.7"},{"l":"IRS Pub. 947 Practice before the IRS and power of attorney","u":"https://www.irs.gov/publications/p947"},{"l":"IRS Annual Filing Season Program","u":"https://www.irs.gov/tax-professionals/annual-filing-season-program"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":1,"rel":["REG-I-A-0001","REG-I-A-0002","REG-I-A-0004","REG-I-A-0008"]},{"id":"CARD-REG-I-A-02","area":"I","group":"A","topic":"Regulations governing practice before the IRS (Circular 230)","title":"Circular 230 duties, fees and conflicts","rules":["§10.20 → submit properly requested IRS records promptly unless good-faith privilege applies","§10.21 → advise client of error or omission + consequences; duty runs to client, not IRS","§10.22 + §10.34 → due diligence; sign a position only with substantial authority, or reasonable basis + disclosure","§10.27 → contingent fee barred except: original-return exam, amended return within 120 days, interest/penalty refund, court case","§10.29 conflict: directly adverse clients need reasonable belief + informed consent confirmed in writing within 30 days","Written consents kept 36 months after the representation ends"],"steps":["Client error found → advise client promptly of error + consequences","IRS asks for records → produce promptly unless good-faith privilege","Fee proposal → contingent? test against four permitted cases","Two clients → directly adverse? consent from every affected client, in writing","Return position → substantial authority, or reasonable basis + disclosure"],"traps":["Client error reported to the IRS by the practitioner; §10.21 requires advising the client only","Contingent fee accepted for preparing an original return or for advice before filing; not one of the four permitted cases"],"ex":{"q":"A CPA agrees to prepare an original 2025 return for a fee equal to 10% of the refund. Is the fee arrangement permitted under Circular 230?","a":"Not permitted. A contingent fee is barred for original-return preparation; allowed only for exam or challenge of a return, amended return within 120 days of exam notice, interest/penalty refund, or court case.","work":["Fee depends on refund → contingent fee","Original return preparation → not an exam, challenge or court case","No permitted case → §10.27(b)(1) bar applies"]},"cites":[{"l":"31 CFR §10.20 Information to be furnished","u":"https://www.ecfr.gov/current/title-31/section-10.20"},{"l":"31 CFR §10.21 Knowledge of client's omission","u":"https://www.ecfr.gov/current/title-31/section-10.21"},{"l":"31 CFR §10.27 Fees","u":"https://www.ecfr.gov/current/title-31/section-10.27"},{"l":"31 CFR §10.29 Conflicting interests","u":"https://www.ecfr.gov/current/title-31/section-10.29"},{"l":"31 CFR §10.34 Standards for tax returns","u":"https://www.ecfr.gov/current/title-31/section-10.34"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":1,"rel":["REG-I-A-0001","REG-I-A-0006","REG-I-A-0009","REG-I-A-1002"]},{"id":"CARD-REG-I-A-03","area":"I","group":"A","topic":"Internal Revenue Code and regulations related to tax return preparers","title":"Preparer penalties and preparer rules","rules":["Preparer = paid to prepare all or a substantial part of a return; signing not required (IRC §7701(a)(36))","Unreasonable position → greater of $1,000 or 50% of income derived (IRC §6694(a))","Willful or reckless understatement → greater of $5,000 or 75% of income derived (IRC §6694(b))","Position safe: substantial authority, or reasonable basis + disclosure; reportable transaction needs more-likely-than-not belief","Due diligence penalty (IRC §6695(g)): EITC, CTC/ACTC/ODC, AOTC, head of household; applies even if credit is correct","Return copy due when presented for signature (§6695(a)); disclosure or use needs consent except to another U.S. preparer (§7216)"],"steps":["Identify preparer: compensation + all or substantial part of the return","Test the position: substantial authority? reasonable basis + disclosure? reportable transaction?","Fails test → unreasonable (50% regime); willful or reckless → 75% regime","Penalty = MAX(fixed floor, rate × income derived from the return)"],"traps":["Floor amount used alone; the percentage of income derived can be larger, so take the greater","Rates mixed: 50% goes with unreasonable position, 75% with willful or reckless conduct"],"ex":{"q":"A preparer is paid $3,000 for a return that contains an unreasonable undisclosed position. What is the §6694(a) penalty? What if the conduct was willful?","a":"Unreasonable position: $1,500. Willful or reckless: $5,000.","work":["Unreasonable: MAX($1,000, 50% × $3,000 = $1,500) = $1,500","Willful: MAX($5,000, 75% × $3,000 = $2,250) = $5,000"]},"cites":[{"l":"IRC §6694 Understatement of taxpayer's liability by tax return preparer","u":"https://www.law.cornell.edu/uscode/text/26/6694"},{"l":"IRC §6695 Other assessable penalties","u":"https://www.law.cornell.edu/uscode/text/26/6695"},{"l":"IRC §7701(a)(36) Tax return preparer","u":"https://www.law.cornell.edu/uscode/text/26/7701"},{"l":"26 CFR §1.6694-2 Standards","u":"https://www.law.cornell.edu/cfr/text/26/1.6694-2"},{"l":"26 CFR §301.7216-2 Permissible disclosures","u":"https://www.law.cornell.edu/cfr/text/26/301.7216-2"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":2,"rel":["REG-I-A-0018","REG-I-A-0020","REG-I-A-0023","REG-I-A-0026"]},{"id":"CARD-REG-I-A-04","area":"I","group":"A","topic":"AICPA Statements on Standards for Tax Services and Code of Professional Conduct","title":"AICPA tax standards and confidentiality","rules":["Prior-year client error → advise client + recommend correction; no duty to notify the IRS","Client information needs consent; exceptions include valid enforceable subpoena or summons and peer review","Reasonable client estimates allowed when exact data impractical; not presented as exact","Return answer left blank only for unavailable information, reasonable uncertainty or immateriality; not for audit risk","Prior returns usable; inquire when client information looks incorrect, incomplete or inconsistent","No duty to update advice for later law changes unless agreed or assisting implementation"],"steps":["Error found → tell client + explain consequences + recommend correction","Third-party request → consent, or exception (subpoena, peer review)","Missing data → reasonable estimate, labeled as an estimate","Advice already given → update only if engagement requires it"],"traps":["Member notifies the IRS of a prior-year error; disclosure needs client consent unless a legal exception applies","Member assumed to owe ongoing advice updates after law changes; the duty exists only by agreement or implementation"],"ex":{"q":"A member prepared a client's 2024 return and, while preparing 2025, finds 2024 income was omitted. What must the member do?","a":"Advise the client promptly of the error and its consequences and recommend correction. No duty to inform the IRS; disclosure without consent is barred.","work":["Error known → advise client (SSTS + Circular 230 §10.21)","IRS notice by member → confidential information, needs consent","Client refuses correction → member may consider withdrawal"]},"cites":[{"l":"AICPA Statements on Standards for Tax Services","u":"https://www.aicpa-cima.com/resources/landing/statements-on-standards-for-tax-services"},{"l":"31 CFR §10.21 (parallel Circular 230 rule)","u":"https://www.ecfr.gov/current/title-31/section-10.21"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":3,"rel":["REG-I-A-0028","REG-I-A-0030","REG-I-A-0032","REG-I-A-0034"]},{"id":"CARD-REG-I-B-01","area":"I","group":"B","topic":"Licensing and disciplinary systems","title":"Circular 230 discipline and sanctions","rules":["OPR administers Circular 230; sanctions: censure, suspension, disbarment, monetary penalty (§10.50)","Censure = public reprimand; right to practice continues","Monetary penalty ≤ gross income derived from the sanctionable conduct (§10.50(c))","Disreputable conduct (§10.51): false information, willful failure to file own return; unsuccessful competent position is not","Expedited suspension (§10.82): within 5 years, license lost for cause, or conviction of tax crime or dishonesty crime","ALJ decision → appeal to Secretary of the Treasury; disbarred practitioner may seek reinstatement after 5 years"],"steps":["Conduct → §10.51 disreputable? (fraud, false information, willful non-filing)","Sanction ladder → censure < suspension < disbarment; monetary penalty capped","Conviction or license loss → expedited suspension route","Decision → ALJ initial decision → Secretary of the Treasury appeal"],"traps":["Penalty measured as 50% or 75% of fee (preparer-penalty measure); Circular 230 cap is gross income derived","Tax Court or IRS Appeals assumed to hear discipline appeals; ALJ decisions go to the Secretary of the Treasury"],"ex":{"q":"A practitioner earned $8,000 from conduct found sanctionable under Circular 230. What is the maximum monetary penalty, and where is the ALJ decision appealed?","a":"Maximum $8,000. Appeal goes to the Secretary of the Treasury.","work":["Cap = gross income derived from the conduct = $8,000","ALJ decision → Secretary of the Treasury (not Tax Court)"]},"cites":[{"l":"31 CFR §10.50 Sanctions","u":"https://www.ecfr.gov/current/title-31/section-10.50"},{"l":"31 CFR §10.51 Incompetence and disreputable conduct","u":"https://www.ecfr.gov/current/title-31/section-10.51"},{"l":"31 CFR §10.78 Appeal of initial decision","u":"https://www.ecfr.gov/current/title-31/section-10.78"},{"l":"31 CFR §10.81 Petition for reinstatement","u":"https://www.ecfr.gov/current/title-31/section-10.81"},{"l":"31 CFR §10.82 Expedited suspension","u":"https://www.ecfr.gov/current/title-31/section-10.82"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":4,"rel":["REG-I-B-0001","REG-I-B-0004","REG-I-B-0007","REG-I-B-0010"]},{"id":"CARD-REG-I-C-01","area":"I","group":"C","topic":"Audits, appeals and the judicial process","title":"Assessment and refund time limits","rules":["Assessment period: 3 years from filing; early return treated as filed on due date (IRC §6501(a),(b)(1))","Omission of more than 25% of gross income stated on the return → 6 years (§6501(e)(1)(A))","False or fraudulent return, willful evasion, or no return → no limit (§6501(c))","Period extended by written agreement made before expiry (§6501(c)(4))","Refund claim: later of 3 years from filing or 2 years from payment (§6511(a))","Refund amount ≤ tax paid in look-back: 3 years + extension, or 2 years (§6511(b)(2))"],"steps":["Find deemed filing date → later of actual filing and due date","Add 3 years; omission > 25% of stated gross income → add 6","Fraud or nonfiler → no expiry","Refund → filing date + 3 years, or payment date + 2 years"],"traps":["Early filing date used as the clock start; the return is treated as filed on the due date","Amended return or >25% omission read as unlimited; omission gives 6 years, only fraud or no return is unlimited"],"ex":{"q":"A calendar-year individual filed the 2025 return on March 1, 2026 (due April 15, 2026), showing gross income of $100,000. IRS later finds $30,000 of omitted income (no fraud). By what date must IRS assess?","a":"April 15, 2032.","work":["Deemed filed April 15, 2026 (due date)","Omitted $30,000 > 25% × $100,000 = $25,000 → 6-year period","April 15, 2026 + 6 years = April 15, 2032"]},"cites":[{"l":"IRC §6501 Limitations on assessment and collection","u":"https://www.law.cornell.edu/uscode/text/26/6501"},{"l":"IRC §6511 Limitations on credit or refund","u":"https://www.law.cornell.edu/uscode/text/26/6511"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":5,"rel":["REG-I-C-0004","REG-I-C-0006","REG-I-C-0011","REG-I-C-1006"]},{"id":"CARD-REG-I-C-02","area":"I","group":"C","topic":"Audits, appeals and the judicial process","title":"Examination, appeals and courts","rules":["Notice of deficiency → 90 days to petition Tax Court (150 if outside U.S.); assessment barred meanwhile (IRC §6213(a))","Tax Court: no prepayment; district court or Court of Federal Claims: pay the tax, then sue for refund","Small tax case (§7463): disputed amount ≤ $50,000 per year; decision not appealable","Appeals: Tax Court → circuit of taxpayer residence (§7482(b)); Court of Federal Claims → Federal Circuit","Summons (§7602) not self-enforcing; IRS petitions district court (§7604); third-party summons: 20 days to begin quash proceeding (§7609(b)(2))","Interview audio recording: taxpayer gives 10 days advance notice, in writing (§7521(a); Pub. 556)"],"steps":["Examination → 30-day letter → Appeals protest","No agreement → notice of deficiency → count 90 days","Choose forum → Tax Court (no prepayment) vs pay-and-sue","Appeal → circuit by residence (Tax Court), Federal Circuit (Court of Federal Claims)"],"traps":["Time limits mixed up: 30 days is the 30-day letter, 120 days is not a period here, 150 days needs an address outside the U.S.","Summons treated as self-enforcing, or enforceable by the Tax Court; only a district court enforces"],"ex":{"q":"A notice of deficiency addressed to a U.S. resident is mailed March 2, 2026. What is the last day to petition the Tax Court?","a":"June 1, 2026.","work":["March 2, 2026 + 90 days = May 31, 2026","May 31, 2026 is a Sunday → next business day (IRC §7503)","Last day = Monday, June 1, 2026"]},"cites":[{"l":"IRC §6213 Restrictions applicable to deficiencies","u":"https://www.law.cornell.edu/uscode/text/26/6213"},{"l":"IRC §7463 Small tax cases","u":"https://www.law.cornell.edu/uscode/text/26/7463"},{"l":"IRC §7482 Courts of review","u":"https://www.law.cornell.edu/uscode/text/26/7482"},{"l":"IRC §7604 Enforcement of summons","u":"https://www.law.cornell.edu/uscode/text/26/7604"},{"l":"IRC §7609 Special procedures for third-party summonses","u":"https://www.law.cornell.edu/uscode/text/26/7609"},{"l":"IRC §7521 Procedures involving taxpayer interviews","u":"https://www.law.cornell.edu/uscode/text/26/7521"},{"l":"IRS Pub. 556 Examination of returns (10-day recording notice)","u":"https://www.irs.gov/publications/p556"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":5,"rel":["REG-I-C-0001","REG-I-C-0005","REG-I-C-0010","REG-I-C-1004"]},{"id":"CARD-REG-I-C-03","area":"I","group":"C","topic":"Substantiation and disclosure","title":"Substantiation, records and disclosure","rules":["Travel, gifts, listed property need strict proof: amount + time + place + business purpose (IRC §274(d))","Receipt needed for lodging and any other expense of $75 or more (Reg. §1.274-5(c)(2)(iii))","Ordinary expenses need reasonable records only (IRC §6001)","Substantial understatement reduced by substantial authority, or adequate disclosure + reasonable basis (§6662(d)(2)(B))","Disclosure on Form 8275; position contrary to a regulation → Form 8275-R; disclosure gives no relief for tax shelters","FBAR (FinCEN 114): aggregate foreign accounts over $10,000 at any time; due April 15, automatic extension to October 15"],"steps":["Expense type → strict category (travel, gifts, listed property) or ordinary","Under $75 non-lodging → log with amount, time, place, purpose","Position weak → substantial authority? else reasonable basis + Form 8275 / 8275-R","Foreign accounts → sum maximum values → over $10,000 → FBAR"],"traps":["Receipt required for every expense; under $75 (other than lodging) a log with the four elements is enough","Disclosure assumed to cure any weak position; no relief for tax shelters, and a position without reasonable basis is not cured"],"ex":{"q":"A taxpayer holds foreign accounts with maximum values of $6,000 (April) and $5,000 (October), each at a different bank. Is an FBAR required? On a business trip, which item needs a receipt: $60 taxi or $60 hotel?","a":"FBAR required: aggregate $11,000 exceeds $10,000. Hotel needs a receipt; taxi under $75 needs only a log.","work":["Sum of maximum account values = $6,000 + $5,000 = $11,000 > $10,000","Lodging always needs a receipt; other expenses under $75 → log entry"]},"cites":[{"l":"IRC §274(d) Substantiation required","u":"https://www.law.cornell.edu/uscode/text/26/274"},{"l":"26 CFR §1.274-5 Substantiation requirements","u":"https://www.law.cornell.edu/cfr/text/26/1.274-5"},{"l":"IRC §6662 Accuracy-related penalty","u":"https://www.law.cornell.edu/uscode/text/26/6662"},{"l":"26 CFR §1.6662-4 Substantial understatement","u":"https://www.law.cornell.edu/cfr/text/26/1.6662-4"},{"l":"IRS: Report of Foreign Bank and Financial Accounts (FBAR)","u":"https://www.irs.gov/businesses/small-businesses-self-employed/report-of-foreign-bank-and-financial-accounts-fbar"},{"l":"31 CFR §1010.306 FBAR filing rules","u":"https://www.ecfr.gov/current/title-31/section-1010.306"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":6,"rel":["REG-I-C-0013","REG-I-C-0015","REG-I-C-0017","REG-I-C-0019"]},{"id":"CARD-REG-I-C-04","area":"I","group":"C","topic":"Taxpayer penalties","title":"Civil penalties and reasonable cause","rules":["Failure to file: 5% per month up to 25%, reduced by failure-to-pay for overlapping months (IRC §6651(a)(1),(c)(1))","Failure to pay: 0.5% per month up to 25%; overlapping months 4.5% + 0.5% = 5% (§6651(a)(2))","Accuracy-related: 20% of underpayment for negligence, substantial understatement, substantial valuation misstatement (§6662)","Gross valuation misstatement (basis 200% or more of correct) → 40% (§6662(h))","Civil fraud → 75%, proved by clear and convincing evidence (§6663)","Reasonable cause + good faith defeats §6662; reliance on an agent to file on time does not (Boyle)"],"steps":["Late return + unpaid tax → months late (part of a month counts)","Combined rate = 5% per overlapping month, capped at 25% for failure to file","Understatement → identify one accuracy ground → 20% (or 40%); no stacking","Fraud proven → 75% replaces accuracy penalty on that portion"],"traps":["Full 5% failure-to-file added to 0.5% failure-to-pay; overlapping months use 4.5% + 0.5%","Rates stacked (20% + 20%, or 20% + 75%) for one underpayment; only one accuracy-related penalty per portion"],"ex":{"q":"A taxpayer files 3 months and 10 days after the due date (4 months or part of a month) with $10,000 of tax unpaid throughout. Compute failure-to-file plus failure-to-pay penalties, ignoring interest.","a":"$2,000.","work":["Failure to file: 4 months × 4.5% = 18% → $1,800","Failure to pay: 4 months × 0.5% = 2% → $200","Total 20% × $10,000 = $2,000"]},"cites":[{"l":"IRC §6651 Failure to file or pay tax","u":"https://www.law.cornell.edu/uscode/text/26/6651"},{"l":"IRC §6662 Accuracy-related penalty","u":"https://www.law.cornell.edu/uscode/text/26/6662"},{"l":"IRC §6663 Civil fraud penalty","u":"https://www.law.cornell.edu/uscode/text/26/6663"},{"l":"IRC §6664 Reasonable cause","u":"https://www.law.cornell.edu/uscode/text/26/6664"},{"l":"IRC §7454 Burden of proof in fraud cases","u":"https://www.law.cornell.edu/uscode/text/26/7454"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":7,"rel":["REG-I-C-0020","REG-I-C-0024","REG-I-C-0028","REG-I-C-1009"]},{"id":"CARD-REG-I-C-05","area":"I","group":"C","topic":"Authoritative hierarchy","title":"Tax authority hierarchy","rules":["Order: Code (statute) → Treasury regulations → revenue rulings and procedures → court decisions and private rulings","Regulations interpret the Code and rank below it (IRC §7805(a))","Private letter ruling binds only the taxpayer who received it; not precedent for others (IRC §6110(k)(3))","Substantial authority includes statutes, regulations, rulings, notices, court cases; excludes treatises and legal periodicals (Reg. §1.6662-4(d)(3))","Position contrary to a regulation → disclose on Form 8275-R"],"steps":["Statute on point → applies, no lower source overrides","Regulation → controls over ruling; ruling → IRS position only","Private ruling → own taxpayer only; other sources supply support, not precedent"],"traps":["Revenue ruling or regulation placed above the Code; the Code outranks all of them","Private letter ruling cited as precedent; only its recipient may rely on it"],"ex":{"q":"A regulation and a private letter ruling issued to another taxpayer conflict on a question. Which controls, and can a third taxpayer rely on the private ruling?","a":"The regulation controls; a third taxpayer may not rely on the private ruling as precedent.","work":["Regulation outranks IRS rulings","PLR limited to the recipient (§6110(k)(3))"]},"cites":[{"l":"IRC §7805 Rules and regulations","u":"https://www.law.cornell.edu/uscode/text/26/7805"},{"l":"IRC §6110 Public inspection of written determinations","u":"https://www.law.cornell.edu/uscode/text/26/6110"},{"l":"26 CFR §1.6662-4 Substantial understatement (substantial authority)","u":"https://www.law.cornell.edu/cfr/text/26/1.6662-4"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":8,"rel":["REG-I-C-0031","REG-I-C-0032"]},{"id":"CARD-REG-I-D-01","area":"I","group":"D","topic":"Legal duties and responsibilities","title":"Privilege, liability and criminal limits","rules":["Tax practitioner privilege (IRC §7525): tax advice, federally authorized practitioner, noncriminal federal tax matters only","Not covered: criminal cases, state matters, SEC proceedings, tax shelter promotion, return preparation information","Couch: no Fifth Amendment shield for records held by an accountant; no federal accountant-client privilege","Kovel: accountant hired by attorney to help give legal advice → attorney-client privilege","Negligence to client = failure of ordinary care; third parties (Ultramares): privity, or fraud / constructive fraud","Criminal limitations: 6 years for evasion and false returns, 3 years general (IRC §6531)"],"steps":["Communication type → tax advice? or return preparation data?","Forum → noncriminal federal tax proceeding? else §7525 unavailable","Waiver check → voluntary disclosure to outsider waives; IRS request does not","Liability → client (negligence, contract, fraud) vs third party (privity rule)"],"traps":["§7525 privilege applied in criminal or state proceedings; it reaches only noncriminal federal tax matters","Taxpayer records held by the accountant assumed protected by the Fifth Amendment; Couch says no"],"ex":{"q":"The IRS summons a CPA's workpapers used to prepare a client's 2024 return; the client invokes the Fifth Amendment and §7525. Is the CPA protected?","a":"No. Fifth Amendment does not protect records in the accountant's hands (Couch), and §7525 does not cover return-preparation information.","work":["Fifth Amendment → personal to the taxpayer; not compelled testimony from the client","§7525 → tax advice only; preparation data excluded","Result → workpapers producible"]},"cites":[{"l":"IRC §7525 Confidentiality privileges","u":"https://www.law.cornell.edu/uscode/text/26/7525"},{"l":"IRC §6531 Criminal prosecution periods","u":"https://www.law.cornell.edu/uscode/text/26/6531"},{"l":"IRC §7203 Willful failure to file","u":"https://www.law.cornell.edu/uscode/text/26/7203"},{"l":"Couch v. United States, 409 U.S. 322 (1973)","u":"https://www.law.cornell.edu/supremecourt/text/409/322"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area1_ethics_procedures","node":9,"rel":["REG-I-D-0001","REG-I-D-0006","REG-I-D-0011","REG-I-D-1002"]},{"id":"CARD-REG-II-A-01","area":"II","group":"A","topic":"Agency: authority of agents and principals","title":"Agent authority","rules":["Actual authority: express (stated) or implied (reasonably necessary to carry out the express grant)","Apparent authority: principal's manifestation to the third party + third party's reasonable belief","Agent's own statements alone never create apparent authority","Ending actual authority does not end apparent authority until the third party is told","Partner binds the partnership for acts apparently in the ordinary course; outside it, all other partners must authorize","Person consenting to be represented as a partner is liable to a relying third party"],"steps":["Grant words → express; needed acts → implied","Third-party facts → principal's manifestation? reasonable reliance?","Agent fired → actual ends; notify prior dealers to end apparent","Partner act → ordinary course? else all-partner authorization"],"traps":["Apparent authority read as arising from the agent's own claims; it comes from the principal's conduct","Firing the agent assumed to end all authority; apparent authority continues toward third parties not notified"],"ex":{"q":"An owner tells the office manager, \"You are in charge of keeping the office running.\" Without asking again, the manager hires a cleaning service. Which authority supports the hiring?","a":"Implied actual authority, since cleaning is reasonably necessary to the express duty.","work":["Express grant → run the office","Cleaning is needed to keep an office running → implied actual authority","Not express: cleaning was never mentioned"]},"cites":[{"l":"UCC §3-402 Signature by representative (agency rules)","u":"https://www.law.cornell.edu/ucc/3/3-402"},{"l":"Cornell Wex: Agency (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/agency"},{"l":"Cornell Wex: Apparent authority (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/apparent_authority"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":2,"rel":["REG-II-A-0007","REG-II-A-0015"]},{"id":"CARD-REG-II-A-02","area":"II","group":"A","topic":"Agency: duties and liabilities of agents and principals","title":"Agent and principal duties and liability","rules":["Agent duties: loyalty (no secret benefit), obedience, care; principal duties: compensation, indemnity for authorized acts","Principal liable for employee torts within scope of employment (respondeat superior)","Disclosed principal: principal bound, agent not; undisclosed principal: agent is a party, principal also bound","Ratification: knowing acceptance of benefits affirms the whole transaction","Agent's knowledge gained within scope is imputed to the principal","Signature clearly in representative form for a named principal → representative not liable on the instrument (UCC §3-402)"],"steps":["Duty breach → loyalty, obedience or care?","Tort → scope of employment? then principal liable too","Contract → principal disclosed, partially disclosed, undisclosed","Unauthorized act → ratification only by full-knowledge acceptance"],"traps":["Employer assumed not liable for an employee's negligence on a delivery route; within scope, it is liable","Ratification limited to the favorable part; a principal cannot keep the benefit and disown the rest"],"ex":{"q":"An agent, acting for an undisclosed principal, signs a supply contract in the agent's own name. Who is liable?","a":"The agent is a party and liable; the principal is also bound once identified.","work":["Undisclosed principal → agent treated as party","Authorized contract → principal also bound"]},"cites":[{"l":"UCC §3-402 Signature by representative","u":"https://www.law.cornell.edu/ucc/3/3-402"},{"l":"Cornell Wex: Respondeat superior (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/respondeat_superior"},{"l":"Cornell Wex: Agency (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/agency"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":1,"rel":["REG-II-A-0005","REG-II-A-0006"]},{"id":"CARD-REG-II-B-01","area":"II","group":"B","topic":"Contracts: formation","title":"Contract formation and sales of goods rules","rules":["Contract = mutual assent + consideration + capacity + legal purpose; bare gift promise lacks consideration","Firm offer (UCC §2-205): merchant, signed writing, irrevocable up to 3 months without consideration","Statute of frauds for goods: signed writing if price $500 or more (UCC §2-201), with exceptions","Modification of a goods contract needs no consideration, only good faith (UCC §2-209)","Mailbox rule: acceptance effective on dispatch; revocation effective on receipt","Added terms in acceptance: contract forms; between merchants they are proposals, excluded if offer limits acceptance (§2-207)"],"steps":["Offer → definite terms communicated","Acceptance → mirror image (common law) or definite expression (UCC)","Consideration → bargained-for exchange, except UCC modification and firm offer","Goods $500 or more → writing or exception"],"traps":["Common-law consideration rule applied to a merchant's firm offer or a UCC modification","Acceptance treated as effective on receipt; under the mailbox rule it is effective on dispatch"],"ex":{"q":"A merchant signs a writing promising to hold an offer to sell goods open for 30 days. On day 10 she revokes. Is the offer still open?","a":"Yes. A merchant's signed firm offer is irrevocable up to 3 months without consideration.","work":["Merchant + signed writing → firm offer","30 days < 3 months → irrevocable","Revocation on day 10 is ineffective"]},"cites":[{"l":"UCC §2-205 Firm offers","u":"https://www.law.cornell.edu/ucc/2/2-205"},{"l":"UCC §2-201 Statute of frauds","u":"https://www.law.cornell.edu/ucc/2/2-201"},{"l":"UCC §2-207 Additional terms in acceptance","u":"https://www.law.cornell.edu/ucc/2/2-207"},{"l":"UCC §2-209 Modification","u":"https://www.law.cornell.edu/ucc/2/2-209"},{"l":"UCC §2-202 Parol evidence","u":"https://www.law.cornell.edu/ucc/2/2-202"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":3,"rel":["REG-II-B-0003","REG-II-B-0001","REG-II-B-0002"]},{"id":"CARD-REG-II-B-02","area":"II","group":"B","topic":"Contracts: performance and discharge","title":"Performance, risk of loss and discharge","rules":["Perfect tender: buyer may reject goods that fail to conform (UCC §2-601); seller may cure within contract time (§2-508)","Substantial performance: recovery = contract price − cost of deficiency","Reasonable insecurity → demand adequate assurance in writing; failure within reasonable time = repudiation (§2-609)","Shipment contract: risk of loss passes to buyer on delivery to carrier (§2-509(1)(a))","Impracticability excuses seller if basic assumption fails; seller allocates supply fairly and notifies (§2-615)","Novation substitutes a party and releases the original obligor"],"steps":["Tender conforms? no → reject, accept, or partial","Time left → seller notice of cure + conforming delivery","Risk of loss → shipment vs destination contract","Discharge route → performance, agreement, novation, impracticability"],"traps":["Substantial performance recovery computed as the deficiency alone; recovery is price less deficiency","Risk of loss placed on the seller until the buyer receives shipment goods; carrier delivery shifts risk in a shipment contract"],"ex":{"q":"A builder substantially performs an $80,000 contract; the deficiency cost is $3,000. What can the builder recover?","a":"$77,000.","work":["Substantial performance → builder may enforce the contract","Recovery = $80,000 − $3,000 = $77,000"]},"cites":[{"l":"UCC §2-601 Buyer's rights on improper delivery","u":"https://www.law.cornell.edu/ucc/2/2-601"},{"l":"UCC §2-508 Cure by seller","u":"https://www.law.cornell.edu/ucc/2/2-508"},{"l":"UCC §2-509 Risk of loss","u":"https://www.law.cornell.edu/ucc/2/2-509"},{"l":"UCC §2-609 Adequate assurance","u":"https://www.law.cornell.edu/ucc/2/2-609"},{"l":"UCC §2-615 Excuse by failure of presupposed conditions","u":"https://www.law.cornell.edu/ucc/2/2-615"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":4,"rel":["REG-II-B-0004","REG-II-B-0015","REG-II-B-0016"]},{"id":"CARD-REG-II-B-03","area":"II","group":"B","topic":"Contracts: breach and remedies","title":"Breach remedies, warranties and limitations","rules":["Buyer cover: (cover price − contract price) × quantity + incidental damages (UCC §2-712)","Seller's damages: contract price − market price + incidental damages (§2-708(1)); action for price for identified goods not resalable (§2-709)","Specific performance for unique goods or other proper circumstances (§2-716)","Statute of limitations for sales: 4 years from accrual, parties may reduce to 1 year, not extend (§2-725)","Implied warranty of merchantability from a merchant; disclaimer must mention merchantability and be conspicuous (§2-314, §2-316)","Limited remedy failing its essential purpose → UCC remedies available (§2-719(2))"],"steps":["Breach by seller → cover, market damages, or specific performance","Breach by buyer → resale or market damages, or price action","Add incidental damages; subtract expenses saved","Check warranty, disclaimer, limitation of remedy, time limit"],"traps":["Cover damages computed as the full cost of substitute goods; only the excess over the contract price counts","Six-year general contract period applied; sales of goods use a 4-year period from accrual"],"ex":{"q":"A buyer covers by purchasing 5,000 units at $3.40; the contract price was $3.00. Incidental damages are $150. What are cover damages?","a":"$2,150.","work":["Price difference = ($3.40 − $3.00) × 5,000 = $2,000","Add incidental damages $150 → $2,150"]},"cites":[{"l":"UCC §2-712 Cover","u":"https://www.law.cornell.edu/ucc/2/2-712"},{"l":"UCC §2-708 Seller's damages","u":"https://www.law.cornell.edu/ucc/2/2-708"},{"l":"UCC §2-709 Action for the price","u":"https://www.law.cornell.edu/ucc/2/2-709"},{"l":"UCC §2-716 Specific performance","u":"https://www.law.cornell.edu/ucc/2/2-716"},{"l":"UCC §2-725 Statute of limitations","u":"https://www.law.cornell.edu/ucc/2/2-725"},{"l":"UCC §2-316 Exclusion of warranties","u":"https://www.law.cornell.edu/ucc/2/2-316"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":5,"rel":["REG-II-B-0005","REG-II-B-0007","REG-II-B-0014","REG-II-B-0021"]},{"id":"CARD-REG-II-C-01","area":"II","group":"C","topic":"Debtor-creditor relationships","title":"Secured transactions and suretyship","rules":["Attachment: value + debtor rights in collateral + authenticated security agreement describing collateral (or possession) (UCC §9-203)","Perfection: filing a financing statement; possession for goods; automatic for consumer-goods purchase-money interest (§9-310, §9-313)","Purchase-money interest perfected within 20 days after debtor takes possession has priority over earlier filer (§9-324(a))","Continuation statement effective only within 6 months before the 5-year lapse (§9-515)","Sale proceeds: reasonable expenses first, then debt; debtor owes deficiency (§9-608, §9-615)","Guarantor who pays: reimbursement from principal debtor + subrogation; creditor extension discharges to extent of loss"],"steps":["Attach → value, rights, agreement or possession","Perfect → file, possess, or automatic","Priority → first to file or perfect; PMSI within 20 days","Default → dispose collateral → expenses → debt → deficiency"],"traps":["Attachment assumed with only value and rights in collateral; a security agreement (or possession) is also required","Sale proceeds applied to debt before expenses; expenses are paid first"],"ex":{"q":"Collateral sells for $38,000; reasonable sale expenses are $3,000; the debt is $60,000. What is the deficiency?","a":"$25,000.","work":["Net proceeds = $38,000 − $3,000 = $35,000","Deficiency = $60,000 − $35,000 = $25,000"]},"cites":[{"l":"UCC §9-203 Attachment and enforceability","u":"https://www.law.cornell.edu/ucc/9/9-203"},{"l":"UCC §9-310 When filing is required to perfect","u":"https://www.law.cornell.edu/ucc/9/9-310"},{"l":"UCC §9-324 Priority of purchase-money security interests","u":"https://www.law.cornell.edu/ucc/9/9-324"},{"l":"UCC §9-515 Duration and effectiveness of financing statement","u":"https://www.law.cornell.edu/ucc/9/9-515"},{"l":"UCC §9-615 Application of proceeds of disposition","u":"https://www.law.cornell.edu/ucc/9/9-615"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":6,"rel":["REG-II-C-0001","REG-II-C-0013","REG-II-C-0019"]},{"id":"CARD-REG-II-D-01","area":"II","group":"D","topic":"Federal laws: qualified health plans","title":"Employer mandate and premium tax credit","rules":["Applicable large employer: full-time employees + part-time hours ÷ 120 ≥ 50 (IRC §4980H(c)(2))","Full-time employee: average at least 30 hours per week or 130 hours per month","§4980H(a): under 95% offered + one credit recipient → payment = amount × (full-time employees − 30)","§4980H(b): lesser of amount × credit recipients or the (a) amount cap","Seasonal exception: workforce over 50 for 120 days or fewer, excess seasonal","Premium credit denied for months with affordable minimum-value employer coverage; repayment cap ends after 2025 [OBBBA]"],"steps":["Count FTEs → full-time + part-time hours ÷ 120","≥ 50 → applicable large employer","95% offer test → (a) or (b) payment","Payment amounts are given in the question"],"traps":["Part-time hours divided by 40 instead of 120 when counting equivalents","Employer payment computed on credit recipients only under (a); it uses all full-time employees less 30"],"ex":{"q":"An employer has 35 full-time employees and part-time employees who worked 3,600 hours in total in a month. Is it an applicable large employer?","a":"Yes. 65 full-time equivalents is at least 50.","work":["Part-time equivalents = 3,600 ÷ 120 = 30","Total = 35 + 30 = 65 ≥ 50"]},"cites":[{"l":"IRC §4980H Shared responsibility for employers","u":"https://www.law.cornell.edu/uscode/text/26/4980H"},{"l":"26 CFR §54.4980H-1 Definitions (130 hours per month)","u":"https://www.law.cornell.edu/cfr/text/26/54.4980H-1"},{"l":"26 CFR §54.4980H-4 Assessable payments (95% offer rule)","u":"https://www.law.cornell.edu/cfr/text/26/54.4980H-4"},{"l":"IRC §36B Premium tax credit","u":"https://www.law.cornell.edu/uscode/text/26/36B"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":7,"rel":["REG-II-D-0001","REG-II-D-0010","REG-II-D-0014","REG-II-D-0026"]},{"id":"CARD-REG-II-D-02","area":"II","group":"D","topic":"Federal laws: worker classification","title":"Employee or independent contractor","rules":["Common-law test: right to control how and by what means the work is done (Reg. §31.3121(d)-1(c))","Evidence groups: behavioral control, financial control, relationship of parties","Labels and forms filed do not control; the substance of control does","Statutory employees for FICA: agent-driver, full-time life insurance salesperson, home worker, traveling salesperson (IRC §3121(d)(3))","Uncertain status → Form SS-8 determination request"],"steps":["Right to direct details → employee","Firm supplies tools and bears profit or loss → contractor factors","Check statutory employee list"],"traps":["Contract label 'independent contractor' treated as controlling; substance of control decides","Full-time insurance salesperson assumed contractor because of no common-law control; the statute makes the person an employee"],"ex":{"q":"A full-time life insurance salesperson works for one insurer under a contract calling her an independent contractor. FICA status?","a":"Statutory employee for FICA.","work":["Full-time life insurance salesperson is a listed category (§3121(d)(3)(B))","Label does not control"]},"cites":[{"l":"IRC §3121 Definitions (employee)","u":"https://www.law.cornell.edu/uscode/text/26/3121"},{"l":"26 CFR §31.3121(d)-1 Who are employees","u":"https://www.law.cornell.edu/cfr/text/26/31.3121(d)-1"},{"l":"IRS Form SS-8 instructions","u":"https://www.irs.gov/instructions/iss8"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":8,"rel":["REG-II-D-0002","REG-II-D-0025"]},{"id":"CARD-REG-II-D-03","area":"II","group":"D","topic":"Federal laws: bankruptcy","title":"Bankruptcy chapters, stay, discharge and avoidance","rules":["Chapter 7: trustee liquidation; Chapter 11: reorganization; Chapter 13: individual repayment plan with regular income","Automatic stay on filing halts civil collection; it does not stay criminal proceedings (11 U.S.C. §362)","Chapter 7 discharge barred if prior chapter 7 discharge in case commenced within 8 years (§727(a)(8))","Nondischargeable: debts obtained by fraud or false pretenses, recent taxes, support, most student loans (§523)","Preference (§547): transfer to creditor on antecedent debt within 90 days (1 year for insiders) while insolvent","Fraudulent transfer: less than reasonably equivalent value within 2 years and insolvent (§548)"],"steps":["Chapter → liquidate (7), reorganize (11), individual plan (13)","Petition → automatic stay, except criminal and support items","Trustee avoidance → preference 90 days / fraudulent 2 years","Distribution → administrative and priority claims first, then general claims pro rata"],"traps":["Chapter 13 described as corporate liquidation; it is an individual repayment plan","Preference reach-back set at 1 year for all creditors; 90 days applies to non-insiders"],"ex":{"q":"An estate has $60,000. Administrative and priority tax claims total $30,000; timely general unsecured claims total $100,000. What does a $20,000 general claim receive?","a":"$6,000.","work":["Left for general claims = $60,000 − $30,000 = $30,000","Payout rate = $30,000 ÷ $100,000 = 30%","30% × $20,000 = $6,000"]},"cites":[{"l":"11 U.S.C. §362 Automatic stay","u":"https://www.law.cornell.edu/uscode/text/11/362"},{"l":"11 U.S.C. §523 Exceptions to discharge","u":"https://www.law.cornell.edu/uscode/text/11/523"},{"l":"11 U.S.C. §547 Preferences","u":"https://www.law.cornell.edu/uscode/text/11/547"},{"l":"11 U.S.C. §548 Fraudulent transfers","u":"https://www.law.cornell.edu/uscode/text/11/548"},{"l":"11 U.S.C. §727 Discharge","u":"https://www.law.cornell.edu/uscode/text/11/727"},{"l":"11 U.S.C. §507 Priorities","u":"https://www.law.cornell.edu/uscode/text/11/507"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":9,"rel":["REG-II-D-0003","REG-II-D-0005","REG-II-D-0017","REG-II-D-0020"]},{"id":"CARD-REG-II-D-04","area":"II","group":"D","topic":"Federal laws: anti-bribery (FCPA)","title":"Foreign Corrupt Practices Act","rules":["Anti-bribery: corrupt offer or payment to a foreign official to obtain or retain business (15 U.S.C. §78dd-1, -2)","Covers issuers, domestic concerns, and payments through intermediaries with knowledge","Exception: facilitating payment for routine governmental action; must be accurately recorded","Affirmative defenses: payment lawful under written local law; reasonable bona fide promotional or contract expenditure","Accounting provisions for issuers: accurate books and records in reasonable detail (§78m(b)(2)(A))","Internal accounting controls duty applies independently of any bribe (§78m(b)(2)(B))"],"steps":["Payer → issuer or domestic concern?","Recipient → foreign official? purpose → obtain or retain business?","Exception or defense → routine action, local law, bona fide expenditure","Books → accurately recorded?"],"traps":["Payment through an agent treated as outside the statute; knowledge that it reaches an official makes it covered","Accounting provisions assumed to apply only if a bribe occurred; internal controls duty stands alone"],"ex":{"q":"A U.S. issuer pays $200 to a foreign clerk to speed processing of a routine permit and records it accurately. Anti-bribery and accounting violation?","a":"No violation under the routine governmental action exception; accurate recording avoids an accounting violation.","work":["Routine governmental action → facilitating payment exception","Accurately recorded → books-and-records satisfied","Local law may still prohibit it"]},"cites":[{"l":"15 U.S.C. §78dd-1 Prohibited foreign trade practices by issuers","u":"https://www.law.cornell.edu/uscode/text/15/78dd-1"},{"l":"15 U.S.C. §78dd-2 Domestic concerns","u":"https://www.law.cornell.edu/uscode/text/15/78dd-2"},{"l":"15 U.S.C. §78m Periodical and other reports (accounting provisions)","u":"https://www.law.cornell.edu/uscode/text/15/78m"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":10,"rel":["REG-II-D-0006","REG-II-D-0007","REG-II-D-0018","REG-II-D-0028"]},{"id":"CARD-REG-II-D-05","area":"II","group":"D","topic":"Federal laws: employment taxes","title":"FICA, FUTA and payroll penalties","rules":["FICA: employee 6.2% Social Security + 1.45% Medicare, employer matches; employee share cannot be waived (IRC §3101, §3111)","Additional Medicare tax 0.9% withheld on wages over $200,000 regardless of filing status","FUTA: employer only; 6.0% on first $7,000 per employee, 5.4% credit for timely state tax → net 0.6% (§3301, §3302)","Deposit penalty: 2% (1-5 days late), 5% (6-15 days), 10% (over 15 days) (§6656)","Trust fund recovery penalty: responsible person who willfully fails to pay over withheld tax (§6672)","Income tax withholding follows Form W-4; quarterly Form 941, annual Form 940"],"steps":["Wages → FICA at 7.65% each side up to wage base","FUTA wage base $7,000 × employees × net rate","Late deposit → days late → penalty tier × deposit"],"traps":["Net FUTA rate applied to all wages; it applies only to the first $7,000 per employee","Employee waiver accepted for FICA; the employer must withhold both parts"],"ex":{"q":"An employer has 10 employees each paid over $7,000; timely state unemployment tax was paid. What is federal FUTA?","a":"$420.","work":["Taxable wages = 10 × $7,000 = $70,000","Net rate = 6.0% − 5.4% = 0.6%","FUTA = $70,000 × 0.6% = $420"]},"cites":[{"l":"IRC §3101 FICA employee rate","u":"https://www.law.cornell.edu/uscode/text/26/3101"},{"l":"IRC §3301 FUTA rate","u":"https://www.law.cornell.edu/uscode/text/26/3301"},{"l":"IRC §3302 Credits against FUTA","u":"https://www.law.cornell.edu/uscode/text/26/3302"},{"l":"IRC §6656 Failure to make deposit","u":"https://www.law.cornell.edu/uscode/text/26/6656"},{"l":"IRC §6672 Trust fund recovery penalty","u":"https://www.law.cornell.edu/uscode/text/26/6672"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":11,"rel":["REG-II-D-0009","REG-II-D-0011","REG-II-D-0023","REG-II-D-0024"]},{"id":"CARD-REG-II-E-01","area":"II","group":"E","topic":"Business structure: selection, formation, operation and termination","title":"Formation and termination of business entities","rules":["General partnership: two or more co-owners carrying on a business for profit; forms without filing; partners jointly and severally liable","Corporation exists when articles are filed (unless delayed effective date); shareholders have limited liability","People acting for a corporation knowing none exists are jointly and severally liable","LLC requires state filing; statute treats company debts as its own, formality lapses not a ground for liability","Partnership at will dissolves on a partner's express will to withdraw; business is then wound up"],"steps":["Two co-owners for profit → partnership by conduct","Filing → corporation or LLC exists","Dissolution event → winding up → termination"],"traps":["Signing incorporation papers assumed to create the corporation; filing creates it","Partnership assumed to need a state filing; co-ownership for profit is enough"],"ex":{"q":"Two friends run a bakery together for profit with no paperwork. What is the entity and liability?","a":"General partnership; partners jointly and severally liable.","work":["Co-owners + business for profit → partnership","No filing needed; liability joint and several"]},"cites":[{"l":"Cornell Wex: Partnership (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/partnership"},{"l":"Cornell Wex: Corporation (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/corporation"},{"l":"Cornell Wex: Limited liability company (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/limited_liability_company_(llc)"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":12,"rel":["REG-II-E-0001","REG-II-E-0003","REG-II-E-0007","REG-II-E-0014"]},{"id":"CARD-REG-II-E-02","area":"II","group":"E","topic":"Business structure: rights, duties and authority of owners and management","title":"Owner and management rights and duties","rules":["General partner: personal liability to outsiders; limited partner protected unless taking part in control","Limited partner voting on amendments or admission of partners is a safe harbor, not control","Default partnership rule: equal share of profits, equal management rights, regardless of capital","Ordinary-course matters: majority of partners; outside ordinary course or amending the agreement: all partners","Corporate directors: duty of care and loyalty; business judgment on process, not outcome","Distribution barred if company would be insolvent or assets fall below liabilities + superior preferences"],"steps":["Owner type → liability exposure","Vote type → ordinary course (majority) vs extraordinary (unanimous)","Distribution test → assets ≥ liabilities + preferences","Director decision → informed, good faith, no conflict"],"traps":["Profits split in proportion to capital by default; the default is equal shares","Director held liable because the decision turned out badly; the standard looks at how the director acted"],"ex":{"q":"Two partners contributed $30,000 and $10,000. The agreement is silent. A $50,000 profit is distributed. What does the first partner receive?","a":"$25,000.","work":["Default: equal share regardless of capital","$50,000 ÷ 2 = $25,000"]},"cites":[{"l":"Cornell Wex: Limited partnership (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/limited_partnership"},{"l":"Cornell Wex: Business judgment rule (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/business_judgment_rule"},{"l":"Cornell Wex: Partnership (overview; primary source is common law or uniform act, not on approved hosts)","u":"https://www.law.cornell.edu/wex/partnership"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area2_business_law","node":13,"rel":["REG-II-E-0002","REG-II-E-0008","REG-II-E-0016"]},{"id":"CARD-REG-III-A-01","area":"III","group":"A","topic":"Basis of assets","title":"Cost basis and lump-sum allocation","rules":["Cost basis = cash paid + liabilities assumed + capitalized acquisition costs (IRC §1012)","Capitalize: sales tax, freight, installation, title search, recording, legal fees to acquire title","Not basis: loan costs (amortized over loan term), insurance, interest, post-installation training","Lump-sum purchase → allocate total cost by relative fair market value (land vs building)","Purchase-money debt is basis from day one; interest on it is expense, not basis","Land is not depreciable; only the building share is recovered"],"steps":["List cost items → price + debt assumed + capitalizable closing costs","Remove non-basis items (loan fees, insurance, interest)","Allocate total: FMV share × total cost","Land share stays; building share enters depreciation"],"traps":["Loan origination fees added to basis; they are amortized over the loan term","Cost allocated by book value or 50/50; the split follows relative fair market value"],"ex":{"q":"A buyer pays $900,000 for land and a building (FMV: land $200,000, building $800,000) plus $10,000 of title, recording and legal fees and $4,000 of loan fees. What is basis of the building?","a":"$728,000.","work":["Total basis = $900,000 + $10,000 = $910,000 (loan fees excluded)","Building share = $800,000 ÷ $1,000,000 = 80%","Building basis = 80% × $910,000 = $728,000; land = $182,000"]},"cites":[{"l":"IRC §1012 Basis of property, cost","u":"https://www.law.cornell.edu/uscode/text/26/1012"},{"l":"IRS Pub. 551 Basis of assets","u":"https://www.irs.gov/publications/p551"},{"l":"IRS Pub. 535 Business expenses","u":"https://www.irs.gov/publications/p535"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area3_property","node":1,"rel":["REG-III-A-0001","REG-III-A-0003","REG-III-A-0005","REG-III-A-0007"]},{"id":"CARD-REG-III-A-02","area":"III","group":"A","topic":"Basis of assets","title":"Adjusted, gift, inherited and converted basis","rules":["Adjusted basis = cost + improvements − depreciation allowed or allowable, whichever is greater (IRC §1016)","Gift: donee takes donor basis; if FMV at gift is lower, that FMV is the basis for a loss (§1015(a))","Gift tax paid on net appreciation increases donee basis (§1015(d))","Inherited: basis = FMV at date of death (or alternate valuation date); holding period long-term (§1014, §1223(9))","Personal → business conversion: basis for depreciation and loss = lesser of adjusted basis or FMV (Reg. §1.168(i)-4(b))","Spouse transfer or divorce transfer: carryover basis, no gain or loss (§1041)"],"steps":["Start → cost or acquisition basis","Add improvements; subtract depreciation allowed or allowable","Gift → compare sale price with donor basis and FMV at gift","Sale price between donor basis and gift-date FMV → no gain, no loss"],"traps":["Gain and loss both measured from donor basis; when FMV at gift is lower, loss uses that FMV","Depreciation reduces basis only when claimed; allowed or allowable reduces basis even if unclaimed"],"ex":{"q":"Donor basis $40,000, FMV at gift $30,000. The donee later sells for $50,000, or alternatively for $25,000. Recognized amount in each case?","a":"$50,000 sale: gain $10,000. $25,000 sale: loss $5,000.","work":["Sale $50,000 > donor basis $40,000 → gain basis $40,000 → gain $10,000","Sale $25,000 < FMV $30,000 → loss basis $30,000 → loss $5,000","Sale between $30,000 and $40,000 → no gain, no loss"]},"cites":[{"l":"IRC §1014 Basis of property acquired from a decedent","u":"https://www.law.cornell.edu/uscode/text/26/1014"},{"l":"IRC §1015 Basis of property acquired by gift","u":"https://www.law.cornell.edu/uscode/text/26/1015"},{"l":"IRC §1016 Adjustments to basis","u":"https://www.law.cornell.edu/uscode/text/26/1016"},{"l":"26 CFR §1.168(i)-4 Changes in use","u":"https://www.law.cornell.edu/cfr/text/26/1.168(i)-4"},{"l":"IRS Pub. 551 Basis of assets","u":"https://www.irs.gov/publications/p551"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area3_property","node":1,"rel":["REG-III-A-0005","REG-III-A-0009","REG-III-A-0013","REG-III-A-0016"]},{"id":"CARD-REG-III-B-01","area":"III","group":"B","topic":"Cost recovery (depreciation and amortization)","title":"MACRS classes and conventions","rules":["5-year: computers, cars, light trucks; 7-year: furniture, most equipment (IRC §168(e)(3))","Residential rental 27.5-year straight-line; nonresidential real property 39-year straight-line; mid-month convention","Half-year convention default for personal property (IRC §168(d))","Mid-quarter convention if more than 40% of the year's personal property basis is placed in service in Q4","40% test: real property excluded; basis reduced by §179, not by bonus (Reg. §1.168(d)-1(b)(4))","Depreciation allowed or allowable reduces basis; land never depreciated"],"steps":["Classify property → recovery period and method","Test Q4 basis ÷ total personal property basis > 40% → mid-quarter, else half-year","Pick table rate by class + convention + year","Depreciation = depreciable basis × table rate"],"traps":["Real property included in the 40% test; only personal property counts","Land included in the 39-year or 27.5-year base; land is never depreciable"],"ex":{"q":"No §179; bonus depreciation elected out. A calendar-year business buys 5-year equipment: $30,000 in February and $40,000 in November. Year-1 depreciation? (mid-quarter 5-year rates: Q1 35%, Q4 5%)","a":"$12,500 (mid-quarter applies).","work":["Q4 share = $40,000 ÷ $70,000 = 57.1% > 40% → mid-quarter","February (Q1): $30,000 × 35% = $10,500","November (Q4): $40,000 × 5% = $2,000 → total $12,500"]},"cites":[{"l":"IRC §168 Accelerated cost recovery system","u":"https://www.law.cornell.edu/uscode/text/26/168"},{"l":"26 CFR §1.168(d)-1 Applicable conventions","u":"https://www.law.cornell.edu/cfr/text/26/1.168(d)-1"},{"l":"IRS Pub. 946 How to depreciate property","u":"https://www.irs.gov/publications/p946"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area3_property","node":2,"rel":["REG-III-B-0001","REG-III-B-0005","REG-III-B-0009","REG-III-B-0016"]},{"id":"CARD-REG-III-B-02","area":"III","group":"B","topic":"Cost recovery (depreciation and amortization)","title":"Section 179, bonus depreciation, listed property and amortization","rules":["§179 2026: limit $2,560,000; reduced dollar-for-dollar above $4,090,000 of §179 property; also capped at business taxable income","Bonus depreciation (§168(k)): 100% for property acquired after Jan. 19, 2025 [OBBBA; tested from 2026-07-01]","Order: §179 first → bonus on the rest → regular MACRS on remaining basis","Listed property (cars): business use must exceed 50% for §179 and MACRS; passenger auto annual caps (§280F)","§197 intangibles: 15-year straight-line from month acquired; start-up and organizational costs: $5,000 first-year deduction, phased out over $50,000","Remaining start-up or organizational costs amortized over 180 months"],"steps":["Cost of qualifying property → §179 amount within dollar limit and income cap","Reduce basis by §179 → apply bonus (if not elected out) → MACRS on remainder","Listed property → business-use % > 50%? else straight-line, no §179","Intangible → 15-year straight-line; start-up cost → $5,000 less excess over $50,000"],"traps":["§179 phase-out ignored, or applied as a percentage; reduction is dollar-for-dollar above the threshold","Listed property at 50% or less business use assumed eligible; business use must exceed 50%"],"ex":{"q":"In 2026 a taxpayer with ample business income places $4,190,000 of qualifying §179 property in service. What is the maximum §179 deduction?","a":"$2,460,000.","work":["Excess over threshold = $4,190,000 − $4,090,000 = $100,000","Limit = $2,560,000 − $100,000 = $2,460,000","Business income cap not binding (ample income)"]},"cites":[{"l":"IRC §179 Election to expense certain depreciable business assets","u":"https://www.law.cornell.edu/uscode/text/26/179"},{"l":"IRC §168(k) Special allowance","u":"https://www.law.cornell.edu/uscode/text/26/168"},{"l":"IRC §280F Limitation on listed property","u":"https://www.law.cornell.edu/uscode/text/26/280F"},{"l":"IRC §197 Amortization of goodwill","u":"https://www.law.cornell.edu/uscode/text/26/197"},{"l":"IRC §195 Start-up expenditures","u":"https://www.law.cornell.edu/uscode/text/26/195"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area3_property","node":2,"rel":["REG-III-B-0002","REG-III-B-0012","REG-III-B-0018","REG-III-B-0024"]},{"id":"CARD-REG-IV-A-01","area":"IV","group":"A","topic":"Gross income (inclusions and exclusions)","title":"Inclusions and exclusions","rules":["Taxable: wages, tips, interest, dividends, unemployment compensation, prizes, punitive damages, guaranteed payments (IRC §61)","Canceled debt is income unless insolvency or bankruptcy exclusion applies (IRC §61(a)(12), §108)","Excluded: gifts and inheritances, life insurance proceeds, state and local bond interest (IRC §102, §101, §103)","Excluded: personal physical injury damages, employer health coverage, workers' compensation (IRC §104, §106)","Employer educational assistance excluded up to $5,250 per year; excess is wages (IRC §127)","Degree-candidate scholarship: tuition, fees, books excluded; room and board taxable (IRC §117)"],"steps":["Item received → income under §61 unless a specific exclusion applies","Test each exclusion: source, purpose, dollar cap","Cap exceeded → excess is wages or other income","Total includible = taxable items + excess over caps"],"traps":["Unemployment compensation treated as excluded; it is fully taxable","Whole educational assistance excluded; only $5,250 per year is excluded, the excess is wages"],"ex":{"q":"An employer pays $8,000 of an employee's graduate tuition under a qualifying educational assistance plan. How much is included in the employee's wages?","a":"$2,750.","work":["Exclusion cap = $5,250","Included = $8,000 − $5,250 = $2,750"]},"cites":[{"l":"IRC §61 Gross income defined","u":"https://www.law.cornell.edu/uscode/text/26/61"},{"l":"IRC §127 Educational assistance programs","u":"https://www.law.cornell.edu/uscode/text/26/127"},{"l":"IRC §103 Interest on State and local bonds","u":"https://www.law.cornell.edu/uscode/text/26/103"},{"l":"IRC §108 Cancellation of debt","u":"https://www.law.cornell.edu/uscode/text/26/108"},{"l":"IRS Pub. 525 Taxable and nontaxable income","u":"https://www.irs.gov/publications/p525"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":1,"rel":["REG-IV-A-0001","REG-IV-A-0009","REG-IV-A-0019","REG-IV-A-0029"]},{"id":"CARD-REG-IV-A-02","area":"IV","group":"A","topic":"Gross income (inclusions and exclusions)","title":"Social Security, annuities and home sale","rules":["Social Security taxable up to 85%; provisional income = other AGI + tax-exempt interest + 50% of benefits (IRC §86)","Base amounts: single $25,000 and $34,000; married filing jointly $32,000 and $44,000","Tier 1: up to 50% of benefits; tier 2: 85% above upper base; total capped at 85% of benefits","Annuity: exclusion ratio = investment ÷ expected return; exclusion stops once investment is recovered (IRC §72)","Home sale exclusion: $250,000 single, $500,000 joint; owned and used 2 of last 5 years (IRC §121)","Qualified dividends and long-term gains use capital gain rates; state bond interest excluded"],"steps":["Provisional income = AGI (without benefits) + tax-exempt interest + 50% of benefits","Below lower base → 0; between bases → up to 50%; above upper base → add 85% of excess","Cap total at 85% × benefits"],"traps":["Only the 85% rate applied from the first dollar; the first tier is limited to 50% of the base spread","Tax-exempt interest left out of provisional income, or benefits counted at 100% instead of 50%"],"ex":{"q":"A married couple filing jointly receives $30,000 of Social Security. Other income included in AGI is $40,000; no tax-exempt interest. How much of the benefits is taxable?","a":"$15,350.","work":["Provisional income = $40,000 + 50% × $30,000 = $55,000","Tier 1 = lesser of 50% × $30,000 = $15,000 or 50% × ($44,000 − $32,000) = $6,000 → $6,000","Tier 2 = 85% × ($55,000 − $44,000) = $9,350","Total $15,350; cap 85% × $30,000 = $25,500 not reached"]},"cites":[{"l":"IRC §86 Social security benefits","u":"https://www.law.cornell.edu/uscode/text/26/86"},{"l":"IRC §72 Annuities","u":"https://www.law.cornell.edu/uscode/text/26/72"},{"l":"IRC §121 Exclusion of gain from sale of principal residence","u":"https://www.law.cornell.edu/uscode/text/26/121"},{"l":"IRS Pub. 915 Social Security benefits","u":"https://www.irs.gov/publications/p915"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":1,"rel":["REG-IV-A-0005","REG-IV-A-0006","REG-IV-A-0033","REG-IV-A-0034"]},{"id":"CARD-REG-IV-B-01","area":"IV","group":"B","topic":"Reporting of items from pass-through entities","title":"Partnership and S corporation items on the owner return","rules":["Partnership and S corporation income passes to owners; separately stated items keep their character (IRC §702(a), §1366(a))","Separately stated: capital gains, §179, charitable contributions, interest, other items that affect owners differently","Partner taxed on distributive share + guaranteed payments whether or not cash is distributed","Cash distributions reduce basis; taxed only when above basis","Loss limits in order: basis → at-risk → passive activity → excess business loss","General partner share and guaranteed payments carry SE tax; S corporation flow-through income does not"],"steps":["K-1 → ordinary income + separately stated items to the right schedules","Add guaranteed payments as ordinary income","Basis → + income, − distributions and losses","Apply loss limits in order"],"traps":["Cash distributed treated as income; income is taxed on the distributive share regardless of cash","Ordinary operating expenses separately stated; only items that affect owners differently are separately stated"],"ex":{"q":"A partner had outside basis $100,000. Her distributive share of ordinary income is $50,000, she received a $20,000 guaranteed payment for services and $30,000 in cash distributions. What income is reported, and what is ending basis?","a":"Reports $70,000 of ordinary income; ending basis $120,000.","work":["Income = $50,000 share + $20,000 guaranteed payment = $70,000","Basis = $100,000 + $50,000 − $30,000 = $120,000 (guaranteed payment is deducted by the partnership; distribution not income)"]},"cites":[{"l":"IRC §702 Income and credits of partner","u":"https://www.law.cornell.edu/uscode/text/26/702"},{"l":"IRC §1366 Pass-through of items to shareholders","u":"https://www.law.cornell.edu/uscode/text/26/1366"},{"l":"IRC §707(c) Guaranteed payments","u":"https://www.law.cornell.edu/uscode/text/26/707"},{"l":"IRC §731 Distributions","u":"https://www.law.cornell.edu/uscode/text/26/731"},{"l":"IRS Pub. 541 Partnerships","u":"https://www.irs.gov/publications/p541"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":2,"rel":["REG-IV-B-0001","REG-IV-B-0006","REG-IV-B-0012"]},{"id":"CARD-REG-IV-C-01","area":"IV","group":"C","topic":"Adjustments and deductions to AGI and taxable income","title":"Adjustments to AGI","rules":["IRA deduction 2026: $7,500 (+ $1,100 age 50 or over); active participant single MAGI phase-out $81,000-$91,000","Active participant, joint return: IRA phase-out MAGI $129,000-$149,000 (Notice 2025-67)","HSA 2026: $4,400 self-only, $8,750 family, + $1,000 age 55 or over; reduced by employer contributions","Student loan interest: max $2,500; 2026 phase-out MAGI $85,000-$100,000 single, $175,000-$205,000 joint","Half of self-employment tax is deducted; educator expense deduction $350 (2026)","Alimony deductible only under pre-2019 instruments; child support never deductible"],"steps":["List adjustments → cap each at its statutory limit","Phase-out fraction = (MAGI − start) ÷ range width","Allowed = limit × (1 − fraction), rounded up to next $10","Adjustments total → AGI"],"traps":["Phase-out treated as all-or-nothing; reduction is ratable across the MAGI range","HSA limit used without subtracting employer contributions or without checking eligibility (HDHP, Medicare, dependent)"],"ex":{"q":"A single taxpayer age 40 covered by a workplace plan has MAGI $86,000 and contributes $7,500 to a traditional IRA. What is the deductible amount?","a":"$3,750.","work":["Fraction = ($86,000 − $81,000) ÷ $10,000 = 50%","Deduction = $7,500 × (1 − 50%) = $3,750"]},"cites":[{"l":"IRC §62 Adjusted gross income defined","u":"https://www.law.cornell.edu/uscode/text/26/62"},{"l":"IRC §219 Retirement savings","u":"https://www.law.cornell.edu/uscode/text/26/219"},{"l":"IRC §223 Health savings accounts","u":"https://www.law.cornell.edu/uscode/text/26/223"},{"l":"IRC §221 Interest on education loans","u":"https://www.law.cornell.edu/uscode/text/26/221"},{"l":"IRS Notice 2025-67 (2026 retirement limits)","u":"https://www.irs.gov/pub/irs-drop/n-25-67.pdf"},{"l":"IRS Rev. Proc. 2025-19 (2026 HSA limits)","u":"https://www.irs.gov/pub/irs-drop/rp-25-19.pdf"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":3,"rel":["REG-IV-C-0001","REG-IV-C-0009","REG-IV-C-0017","REG-IV-C-0027"]},{"id":"CARD-REG-IV-C-02","area":"IV","group":"C","topic":"Adjustments and deductions to AGI and taxable income","title":"Itemized deductions and the SALT cap","rules":["Itemize when total exceeds standard deduction: $16,100 single, $24,150 head of household, $32,200 joint (2026)","SALT cap 2026: $40,400, reduced by 30% of MAGI over $505,000, not below $10,000 [OBBBA; tested from 2026-07-01]","Medical expenses deductible only above 7.5% of AGI (IRC §213)","Mortgage interest: acquisition debt up to $750,000; home equity interest only if funds improve the home","Cash gifts to public charities up to 60% of AGI; itemized gifts face 0.5% AGI floor from 2026 [OBBBA]","Miscellaneous itemized deductions disallowed; personal casualty loss only in a declared disaster"],"steps":["Add itemized categories → apply floors and caps","SALT = lesser of taxes paid or cap after phase-down","Compare total with standard deduction → larger"],"traps":["Old $10,000 SALT cap used, or phase-down ignored; 2026 cap $40,400 phases down above $505,000 MAGI","Medical floor read as 10% of AGI; the floor is 7.5%"],"ex":{"q":"In 2026 a taxpayer has MAGI $545,000 and paid $60,000 of state and local taxes. What SALT deduction is allowed?","a":"$28,400.","work":["Excess MAGI = $545,000 − $505,000 = $40,000","Reduction = 30% × $40,000 = $12,000","Cap = $40,400 − $12,000 = $28,400 (above $10,000 floor) → deduct $28,400"]},"cites":[{"l":"IRC §164(b)(7) State and local tax limitation","u":"https://www.law.cornell.edu/uscode/text/26/164"},{"l":"IRC §213 Medical expenses","u":"https://www.law.cornell.edu/uscode/text/26/213"},{"l":"IRC §163(h) Home mortgage interest","u":"https://www.law.cornell.edu/uscode/text/26/163"},{"l":"IRC §170 Charitable contributions","u":"https://www.law.cornell.edu/uscode/text/26/170"},{"l":"IRC §63 Taxable income defined","u":"https://www.law.cornell.edu/uscode/text/26/63"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":3,"rel":["REG-IV-C-0010","REG-IV-C-0015","REG-IV-C-0021","REG-IV-C-0032"]},{"id":"CARD-REG-IV-C-03","area":"IV","group":"C","topic":"Adjustments and deductions to AGI and taxable income","title":"Standard deduction, QBI and OBBBA deductions","rules":["Standard deduction 2026: $16,100 single or MFS, $24,150 HOH, $32,200 joint; add $1,650 age 65+ or blind ($2,050 unmarried)","Dependent standard deduction: greater of $1,350 or earned income + $450, not above the basic amount","QBI deduction 20%; wage/property limit and SSTB exclusion apply above $201,750 single, $403,500 joint (2026)","Tips ≤ $25,000; overtime premium ≤ $12,500 ($25,000 joint), 2025-2028; phase out above MAGI $150,000 ($300,000 joint) [OBBBA]","Senior deduction $6,000 per person age 65+, 2025-2028; reduced 6% of MAGI over $75,000 ($150,000 joint) [OBBBA]","Auto loan interest ≤ $10,000 on new U.S.-assembled personal vehicle; phase-out above MAGI $100,000 ($200,000 joint) [OBBBA]"],"steps":["Basic amount by filing status + additional amounts","OBBBA deduction → each person: cap − phase-out reduction (6% × excess MAGI for seniors)","Sum for the return; available with or without itemizing"],"traps":["Senior deduction reduced once on a combined $12,000; reduce each spouse's $6,000 by 6% of excess MAGI, then add","Additional standard deduction $2,050 used for married taxpayers; $2,050 is for unmarried, $1,650 for married"],"ex":{"q":"A married couple filing jointly, both age 66, has MAGI $170,000 in 2026. What is the OBBBA senior deduction?","a":"$9,600.","work":["Excess MAGI = $170,000 − $150,000 = $20,000","Reduction per person = 6% × $20,000 = $1,200","Each $6,000 − $1,200 = $4,800; two people → $9,600"]},"cites":[{"l":"IRC §63(c) Standard deduction","u":"https://www.law.cornell.edu/uscode/text/26/63"},{"l":"IRC §199A Qualified business income","u":"https://www.law.cornell.edu/uscode/text/26/199A"},{"l":"IRS: OBBBA deductions for working Americans and seniors","u":"https://www.irs.gov/newsroom/one-big-beautiful-bill-act-tax-deductions-for-working-americans-and-seniors"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":3,"rel":["REG-IV-C-0021","REG-IV-C-0024","REG-IV-C-0028","REG-IV-C-0034"]},{"id":"CARD-REG-IV-D-01","area":"IV","group":"D","topic":"Loss limitations","title":"Capital losses, wash sales and other loss rules","rules":["Net capital loss deduction ≤ $3,000 ($1,500 MFS); excess carries forward indefinitely, keeping character (IRC §1211(b), §1212(b))","Wash sale: identical stock bought within 30 days before or after sale; loss added to new basis (§1091)","Personal-use property losses not deductible; investment property losses are (IRC §165(c))","Loss on sale to a related party disallowed; worthless securities treated as sold on last day of year (§267, §165(g))","§1244 stock: ordinary loss up to $50,000 ($100,000 joint) per year","NOL carried forward indefinitely; deduction ≤ 80% of taxable income (IRC §172)"],"steps":["Net short-term and long-term separately → combine net results","Net loss → deduct up to $3,000 against ordinary income","Remainder → carryforward, same short or long character","Wash sale → disallow loss, add to replacement basis"],"traps":["Full capital loss deducted in one year; only $3,000 ($1,500 MFS) per year, remainder carries forward","Loss on personal-use property (car, home, furniture) deducted; only investment or business property losses count"],"ex":{"q":"A taxpayer has a $2,000 long-term capital gain and a $9,000 short-term capital loss. What is deducted against ordinary income, and what carries forward?","a":"Deduct $3,000; carry forward $4,000 (short-term).","work":["Net = $2,000 − $9,000 = net loss $7,000 (short-term)","Deduct $3,000 → carryforward $7,000 − $3,000 = $4,000 short-term"]},"cites":[{"l":"IRC §1211 Limitation on capital losses","u":"https://www.law.cornell.edu/uscode/text/26/1211"},{"l":"IRC §1212 Capital loss carrybacks and carryovers","u":"https://www.law.cornell.edu/uscode/text/26/1212"},{"l":"IRC §1091 Wash sales","u":"https://www.law.cornell.edu/uscode/text/26/1091"},{"l":"IRC §165 Losses","u":"https://www.law.cornell.edu/uscode/text/26/165"},{"l":"IRC §1244 Small business stock","u":"https://www.law.cornell.edu/uscode/text/26/1244"},{"l":"IRS Pub. 550 Investment income and expenses","u":"https://www.irs.gov/publications/p550"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":4,"rel":["REG-IV-D-0001","REG-IV-D-0011","REG-IV-D-0019","REG-IV-D-0026"]},{"id":"CARD-REG-IV-D-02","area":"IV","group":"D","topic":"Loss limitations","title":"Basis, at-risk, passive activity and excess business loss","rules":["Loss limit order: stock or outside basis → at-risk (§465) → passive activity (§469) → excess business loss (§461(l))","Passive losses offset passive income only; suspended losses released on full taxable disposition to an unrelated party","Rental allowance $25,000 with active participation; reduced 50% of MAGI over $100,000; gone at $150,000 (§469(i))","Real estate professional: over 750 hours and more than half of personal services in real property trades","Excess business loss 2026: above $256,000 ($512,000 joint) → NOL carryforward; limit permanent [OBBBA; tested from 2026-07-01]","Partner loss limited to outside basis; excess carried forward until basis restored (§704(d))"],"steps":["Basis first → loss allowed up to basis","At-risk amount next → then passive activity test","Passive rental → $25,000 allowance less 50% × (MAGI − $100,000)","Aggregate business loss > threshold → excess becomes NOL"],"traps":["Rental allowance not reduced by MAGI; the $25,000 falls 50 cents per dollar above $100,000 and vanishes at $150,000","Passive loss used against wages or portfolio income; it offsets only passive income until disposition"],"ex":{"q":"A taxpayer with MAGI $120,000 actively manages a rental with a $30,000 loss and no passive income. What loss is deductible and what is suspended?","a":"Deductible $15,000; suspended $15,000.","work":["Allowance = $25,000 − 50% × ($120,000 − $100,000) = $15,000","Suspended = $30,000 − $15,000 = $15,000 carried forward"]},"cites":[{"l":"IRC §469 Passive activity losses","u":"https://www.law.cornell.edu/uscode/text/26/469"},{"l":"IRC §465 Deductions limited to amount at risk","u":"https://www.law.cornell.edu/uscode/text/26/465"},{"l":"IRC §461(l) Excess business losses","u":"https://www.law.cornell.edu/uscode/text/26/461"},{"l":"IRC §704(d) Partner loss limitation","u":"https://www.law.cornell.edu/uscode/text/26/704"},{"l":"IRS Pub. 925 Passive activity and at-risk rules","u":"https://www.irs.gov/publications/p925"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":4,"rel":["REG-IV-D-0003","REG-IV-D-0011","REG-IV-D-0016"]},{"id":"CARD-REG-IV-E-01","area":"IV","group":"E","topic":"Filing status","title":"Filing status and dependents","rules":["Married at year end → joint or separate; year of spouse death → joint if survivor not remarried (IRC §7703)","Head of household: unmarried, pays over half of home costs for qualifying person living there over half year","Parent can be HOH qualifying person without living with taxpayer, if taxpayer pays over half of parent's home costs","Qualifying surviving spouse: 2 years after death year, dependent child, not remarried; joint rates and standard deduction","Considered unmarried: spouse absent last 6 months and taxpayer's child lives there over half year (§7703(b))","Qualifying relative 2026: gross income under $5,300, taxpayer provides over half of support (IRC §152(d))"],"steps":["Marital status at Dec. 31 → married / unmarried / considered unmarried","Dependent? qualifying child tests (relationship, age, residency, support) or qualifying relative tests","Home costs paid > 50% + qualifying person → HOH","Year of spouse death + 2 years with dependent child → qualifying surviving spouse"],"traps":["Cousin or unrelated person treated as qualifying relative without living all year in the household","Head of household claimed while married and living together; considered unmarried needs spouse absent last 6 months"],"ex":{"q":"A widow, age 66, whose husband died in 2025 has not remarried and supports a dependent child living with her in 2026. What is her filing status and standard deduction?","a":"Qualifying surviving spouse; standard deduction $33,850.","work":["Year of death 2025 → 2026 is first of two following years → qualifying surviving spouse","Standard deduction = $32,200 + $1,650 (age 65, not treated as unmarried) = $33,850"]},"cites":[{"l":"IRC §2 Definitions and special rules","u":"https://www.law.cornell.edu/uscode/text/26/2"},{"l":"IRC §7703 Determination of marital status","u":"https://www.law.cornell.edu/uscode/text/26/7703"},{"l":"IRC §6013 Joint returns (year of death)","u":"https://www.law.cornell.edu/uscode/text/26/6013"},{"l":"IRC §152 Dependent defined","u":"https://www.law.cornell.edu/uscode/text/26/152"},{"l":"IRS Pub. 501 Dependents, standard deduction, and filing information","u":"https://www.irs.gov/publications/p501"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":5,"rel":["REG-IV-E-0001","REG-IV-E-0007","REG-IV-E-0013"]},{"id":"CARD-REG-IV-F-01","area":"IV","group":"F","topic":"Computation of tax and credits","title":"Tax rates, capital gains, kiddie tax, AMT and NIIT","rules":["2026 single brackets: 10% to $12,400; 12% to $50,400; 22% to $105,700; 24% to $201,775; 32% to $256,225","Single: 35% to $640,600, 37% above; joint 37% above $768,700 (Rev. Proc. 2025-32)","Long-term gain 2026: 0% up to $49,450 single, $98,900 joint; 15% up to $545,500 single, $613,700 joint","Kiddie tax 2026: child's unearned income above $2,700 taxed at parent's rate","AMT 2026: exemption $90,100 single, $140,200 joint; 26% up to $244,500 of excess, 28% above","NIIT 3.8% on lesser of net investment income or MAGI over $200,000 single, $250,000 joint"],"steps":["Taxable income → split ordinary vs preferential gains (collectibles 28%, unrecaptured §1250 25%)","Ordinary tax from bracket table","Gains stack on top of ordinary income → 0 / 15 / 20% by threshold","Add AMT, NIIT and other taxes"],"traps":["Gain taxed at 0% although ordinary income already exceeds the 0% threshold; gains stack above ordinary income","Kiddie tax exclusion read as $1,350 only; net unearned income above $2,700 is taxed at parent's rate"],"ex":{"q":"A single taxpayer has taxable income $100,000 in 2026, including $20,000 of qualified dividends and long-term gain. Compute regular tax.","a":"$15,312.","work":["Ordinary income = $80,000 → $5,800 + 22% × ($80,000 − $50,400) = $12,312","Preferential $20,000 sits above $49,450 and below $545,500 → 15% = $3,000","Total = $15,312"]},"cites":[{"l":"IRC §1 Tax imposed","u":"https://www.law.cornell.edu/uscode/text/26/1"},{"l":"IRC §55 Alternative minimum tax imposed","u":"https://www.law.cornell.edu/uscode/text/26/55"},{"l":"IRC §1411 Net investment income tax","u":"https://www.law.cornell.edu/uscode/text/26/1411"},{"l":"IRS Pub. 550 Investment income and expenses","u":"https://www.irs.gov/publications/p550"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":6,"rel":["REG-IV-F-0005","REG-IV-F-0014","REG-IV-F-0024"]},{"id":"CARD-REG-IV-F-02","area":"IV","group":"F","topic":"Computation of tax and credits","title":"Tax credits","rules":["Refundable: EITC, additional child tax credit, AOTC (40%); nonrefundable: lifetime learning, dependent care, foreign tax credit","Child tax credit 2026: $2,200 per child under 17; refundable to $1,700; $50 less per $1,000 MAGI over threshold","AOTC: up to $2,500 per student, first 4 years, 40% refundable; lifetime learning: 20% of first $10,000, nonrefundable","Dependent care 2026: 50% of up to $3,000 (one) or $6,000 (two+), stepping to 35%, 20% [OBBBA; from 2026-07-01]","EITC 2026: investment income limit $12,200; maximum credit $8,231 with three or more children","Clean vehicle credit ends for vehicles acquired after Sept. 30, 2025; residential energy credit ends after 2025 [OBBBA]"],"steps":["Tentative tax → subtract nonrefundable credits (not below zero)","Add refundable credits → payment or refund","Child tax credit → count children under 17 with SSN, less phase-out"],"traps":["Lifetime learning or dependent care credit treated as refundable; only EITC, ACTC and 40% of AOTC refund","Phase-out applied per child; the $50 reduction applies per $1,000 (or part) of MAGI over the threshold on the total credit"],"ex":{"q":"A married couple filing jointly has two children under 17 and MAGI $420,000 in 2026. What is the child tax credit before the tax-liability limit?","a":"$3,400.","work":["Credit before phase-out = 2 × $2,200 = $4,400","Threshold $400,000 (joint); excess MAGI = $420,000 − $400,000 = $20,000 → 20 × $1,000 → $50 × 20 = $1,000","Credit = $4,400 − $1,000 = $3,400"]},"cites":[{"l":"IRC §24 Child tax credit","u":"https://www.law.cornell.edu/uscode/text/26/24"},{"l":"IRC §25A American opportunity and lifetime learning credits","u":"https://www.law.cornell.edu/uscode/text/26/25A"},{"l":"IRC §21 Dependent care credit","u":"https://www.law.cornell.edu/uscode/text/26/21"},{"l":"IRC §32 Earned income credit","u":"https://www.law.cornell.edu/uscode/text/26/32"},{"l":"IRC §30D New clean vehicles (terminated)","u":"https://www.law.cornell.edu/uscode/text/26/30D"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":6,"rel":["REG-IV-F-0001","REG-IV-F-0011","REG-IV-F-0020","REG-IV-F-0029"]},{"id":"CARD-REG-IV-F-03","area":"IV","group":"F","topic":"Computation of tax and credits","title":"Estimated tax, self-employment tax and payroll taxes","rules":["Calendar-year estimated tax due April 15, June 15, September 15, January 15","Safe harbor: lesser of 90% of current-year tax or 100% of prior-year tax (110% if prior AGI over $150,000)","No estimated tax penalty if tax owed after withholding and credits is under $1,000 (IRC §6654(e))","SE tax 15.3% = 12.4% Social Security up to wage base + 2.9% Medicare, on 92.35% of net earnings","Half of SE tax deducted above the line; Additional Medicare tax 0.9% over $200,000 ($250,000 joint)","Withholding treated as paid evenly through the year; estimated payments count when made"],"steps":["Net SE profit × 92.35% → SE base","SE base × 15.3% (12.4% only up to wage base) → SE tax","Half of SE tax → deduction","Required annual payment = lesser of 90% current or 100% / 110% prior; ÷ 4"],"traps":["SE tax applied to 100% of profit; the base is 92.35% of net earnings","Prior-year safe harbor at 100% used when prior AGI exceeds $150,000; the rate is 110%"],"ex":{"q":"A sole proprietor has $100,000 of net SE profit, below the Social Security wage base. Compute SE tax and the above-the-line deduction.","a":"SE tax $14,129.55; deduction $7,064.78.","work":["Base = $100,000 × 92.35% = $92,350","SE tax = $92,350 × 15.3% = $14,129.55","Deduction = 50% × $14,129.55 = $7,064.78"]},"cites":[{"l":"IRC §6654 Estimated tax penalty","u":"https://www.law.cornell.edu/uscode/text/26/6654"},{"l":"IRC §1401 Rate of tax (SE tax)","u":"https://www.law.cornell.edu/uscode/text/26/1401"},{"l":"IRC §1402 Net earnings from self-employment","u":"https://www.law.cornell.edu/uscode/text/26/1402"},{"l":"IRC §164(f) Deduction for one-half of SE tax","u":"https://www.law.cornell.edu/uscode/text/26/164"},{"l":"IRS Pub. 334 Tax guide for small business (92.35% of net earnings)","u":"https://www.irs.gov/publications/p334"},{"l":"IRS Pub. 505 Tax withholding and estimated tax","u":"https://www.irs.gov/publications/p505"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area4_individuals","node":6,"rel":["REG-IV-F-0002","REG-IV-F-0003","REG-IV-F-0017","REG-IV-F-0030"]},{"id":"CARD-REG-V-A-01","area":"V","group":"A","topic":"Differences between book and tax income (loss)","title":"Book-tax differences and Schedules M-1 and M-3","rules":["Permanent differences never reverse: tax-exempt interest, fines and penalties, federal income tax expense, nondeductible meals","Temporary differences reverse later: MACRS vs book depreciation, warranty and bad debt reserves, prepaid income","Schedule M-1 adds: federal income tax, excess capital loss, nondeductible expenses; subtracts: tax-exempt interest, excess tax depreciation","Total assets of $10 million or more at year-end → Schedule M-3 instead of M-1","100% bonus depreciation permanent for property acquired after Jan. 19, 2025 [OBBBA; tested from 2026-07-01]","Domestic research costs expensed under new §174A for tax years beginning after 2024; foreign research 15-year amortization [OBBBA]"],"steps":["Start with net income per books","Add: federal income tax, nondeductible items, income on return not on books","Subtract: tax-exempt income, deductions on return not on books","Result = taxable income before NOL and special deductions"],"traps":["Fines and tax-exempt interest treated as temporary differences; both are permanent","Excess tax depreciation added on Schedule M-1; it is subtracted because the tax deduction exceeds book"],"ex":{"q":"Net income per books $400,000 includes: federal income tax expense $84,000, fines $5,000 (nondeductible), nondeductible meals $6,000, tax-exempt interest income $15,000. Tax depreciation exceeds book by $40,000. What is taxable income before NOL and special deductions?","a":"$440,000.","work":["$400,000 + $84,000 + $5,000 + $6,000 = $495,000","Subtract $15,000 tax-exempt interest and $40,000 excess depreciation","$495,000 − $55,000 = $440,000"]},"cites":[{"l":"Instructions for Form 1120 (Schedules M-1, M-3)","u":"https://www.irs.gov/instructions/i1120"},{"l":"IRC §103 Interest on state and local bonds","u":"https://www.law.cornell.edu/uscode/text/26/103"},{"l":"IRC §162(f) Fines and penalties","u":"https://www.law.cornell.edu/uscode/text/26/162"},{"l":"IRC §168(k) Special depreciation allowance","u":"https://www.law.cornell.edu/uscode/text/26/168"},{"l":"IRC §174A Domestic research expenditures","u":"https://www.law.cornell.edu/uscode/text/26/174A"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area5_entities","node":1,"rel":["REG-V-A-0001","REG-V-A-0007","REG-V-A-0013","REG-V-A-0019"]},{"id":"CARD-REG-V-B-01","area":"V","group":"B","topic":"C corporations — computation of taxable income, tax liability and allowable credits","title":"C corporation taxable income and tax","rules":["Federal rate 21% of taxable income (IRC §11(b))","DRD: 50% under 20% ownership, 65% for 20% to under 80%, 100% qualifying affiliated dividends; holding period over 45 days","DRD limited to percentage of taxable income before DRD, unless the DRD creates or increases a loss","Charity: only contributions above 1% and up to 10% of taxable income deductible; 5-year carryforward [OBBBA; 2026-07-01]","Capital losses offset capital gains only: carry back 3 years, forward 5 years","NOL: no carryback, indefinite carryforward, deduction ≤ 80% of taxable income"],"steps":["Gross income → ordinary deductions → taxable income before charity and DRD","Charity → deduct the band from 1% to 10% of income before charity and DRD; rest carried forward","DRD → percentage × dividends, capped at percentage × income after charity","Tax = 21% × taxable income"],"traps":["DRD limit measured on income after the DRD; the limit uses taxable income before the DRD","Charity limits measured after the DRD; the base is income before charity and before DRD"],"ex":{"q":"A calendar-year C corporation has taxable income before charity and DRD of $400,000, including $50,000 of dividends from a 30%-owned corporation. It paid $60,000 in qualifying cash contributions. What is 2026 federal tax?","a":"$69,615.","work":["Band: floor 1% × $400,000 = $4,000; ceiling 10% × $400,000 = $40,000 → deduct $40,000 − $4,000 = $36,000; $24,000 carried forward","Income after charity = $364,000; DRD = 65% × $50,000 = $32,500 (limit 65% × $364,000 = $236,600)","Taxable income = $364,000 − $32,500 = $331,500; tax = 21% × $331,500 = $69,615"]},"cites":[{"l":"IRC §11 Tax imposed","u":"https://www.law.cornell.edu/uscode/text/26/11"},{"l":"IRC §243 Dividends received by corporations","u":"https://www.law.cornell.edu/uscode/text/26/243"},{"l":"IRC §170(b)(2) Corporate charitable limit","u":"https://www.law.cornell.edu/uscode/text/26/170"},{"l":"IRC §172 Net operating loss","u":"https://www.law.cornell.edu/uscode/text/26/172"},{"l":"IRC §1212(a) Corporate capital loss carryovers","u":"https://www.law.cornell.edu/uscode/text/26/1212"},{"l":"Instructions for Form 1120","u":"https://www.irs.gov/instructions/i1120"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area5_entities","node":2,"rel":["REG-V-B-0001","REG-V-B-0006","REG-V-B-0013","REG-V-B-0020"]},{"id":"CARD-REG-V-B-02","area":"V","group":"B","topic":"C corporations — state and local tax issues","title":"State income tax nexus and apportionment","rules":["P.L. 86-272 protects solicitation of orders for tangible goods approved and shipped from outside the state","Repairs, installation, or stocked inventory in the state exceed solicitation → nexus","Economic nexus (Wayfair): sales above a state threshold create collection duty without physical presence","Business income apportioned by formula (property, payroll, sales); many states use single sales factor","Nonbusiness income allocated to a specific state, not apportioned","State taxable income = apportioned business income + nonbusiness income allocated to the state"],"steps":["Nexus test → physical presence or economic threshold; P.L. 86-272 protection?","Split income → business (apportion) vs nonbusiness (allocate)","Apply the state formula factor × business income","Add allocated nonbusiness income"],"traps":["P.L. 86-272 shielding a company whose employees repair or install products in the state","Nonbusiness income apportioned by the sales factor; it is allocated to the state of situs or domicile"],"ex":{"q":"A corporation has business income of $1,000,000; State X sales are $2,000,000 of $10,000,000 total. State X uses a single sales factor. It also has $30,000 of nonbusiness rent from State X property. What is State X taxable income?","a":"$230,000.","work":["Sales factor = $2,000,000 ÷ $10,000,000 = 20%","Apportioned business income = 20% × $1,000,000 = $200,000","Plus allocated nonbusiness rent $30,000 = $230,000"]},"cites":[{"l":"15 U.S.C. §381 Imposition of net income tax (P.L. 86-272)","u":"https://www.law.cornell.edu/uscode/text/15/381"},{"l":"South Dakota v. Wayfair, Inc., 585 U.S. ___ (2018)","u":"https://www.law.cornell.edu/supremecourt/text/17-494"},{"l":"IRC §164 Taxes (state income tax deduction)","u":"https://www.law.cornell.edu/uscode/text/26/164"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":3,"rel":["REG-V-B-0023","REG-V-B-0025","REG-V-B-0027","REG-V-B-0029"]},{"id":"CARD-REG-V-B-03","area":"V","group":"B","topic":"C corporations — formation, distributions and liquidation (supplement)","title":"Formation of a corporation (§351)","rules":["§351: property transferred for stock, transferors control 80% immediately after → no gain or loss (IRC §351(a))","Boot received → gain recognized = lesser of realized gain or boot; losses never recognized","Stock basis = property basis + gain recognized − boot received − liabilities assumed (§358)","Corporation basis = transferor basis + gain recognized (§362(a))","Liabilities assumed exceeding property basis → gain recognized (§357(c))","Stock for services is compensation at FMV; services stock does not count toward 80% control"],"steps":["Realized gain = FMV received − basis given","Recognized gain = lesser of realized gain or boot","Stock basis = basis given + recognized gain − boot","Corporation basis = shareholder basis + recognized gain"],"traps":["All realized gain recognized; only boot triggers gain, capped at realized gain","Stock basis set to FMV; it is carryover basis, less boot, plus gain recognized"],"ex":{"q":"A transfers property (basis $40,000, FMV $100,000) to a new corporation for stock worth $90,000 and $10,000 cash; A controls the corporation. Gain recognized, stock basis, and corporation's basis in the property?","a":"Gain $10,000; stock basis $40,000; corporation basis $50,000.","work":["Realized gain = $100,000 − $40,000 = $60,000; boot $10,000 → recognized $10,000","Stock basis = $40,000 + $10,000 − $10,000 = $40,000","Corporation basis = $40,000 + $10,000 = $50,000"]},"cites":[{"l":"IRC §351 Transfer to corporation controlled by transferor","u":"https://www.law.cornell.edu/uscode/text/26/351"},{"l":"IRC §358 Basis to distributees","u":"https://www.law.cornell.edu/uscode/text/26/358"},{"l":"IRC §357 Assumption of liability","u":"https://www.law.cornell.edu/uscode/text/26/357"},{"l":"IRC §362 Basis to corporations","u":"https://www.law.cornell.edu/uscode/text/26/362"},{"l":"IRS Pub. 542 Corporations","u":"https://www.irs.gov/publications/p542"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":4,"rel":["REG-V-B-0031","REG-V-B-0033","REG-V-B-0036","REG-V-B-1002"]},{"id":"CARD-REG-V-B-04","area":"V","group":"B","topic":"C corporations — formation, distributions and liquidation (supplement)","title":"Corporate distributions and liquidation","rules":["Dividend to extent of current or accumulated E&P; current E&P counts despite an accumulated deficit (IRC §316)","Then return of capital reduces stock basis; excess is capital gain (IRC §301(c))","Distributing appreciated property → corporation recognizes gain; shareholder basis = FMV (§311(b), §301(d))","Complete liquidation: shareholder gain or loss = FMV received − stock basis (§331)","Liquidating corporation recognizes gain or loss on property distributed (§336(a))","Subsidiary (80% owned) liquidation into parent: no gain or loss, carryover basis (§332, §334(b))"],"steps":["Distribution amount → cash + FMV of property","Apply to current E&P first → then accumulated E&P → dividend","Remainder → reduce stock basis → excess capital gain"],"traps":["Accumulated E&P deficit used to offset current E&P; current E&P alone makes a dividend","Return of capital taxed as dividend; it first reduces basis and only the excess is capital gain"],"ex":{"q":"A corporation has current E&P of $30,000 and an accumulated E&P deficit of $10,000. It distributes $50,000 cash to its sole shareholder, whose stock basis is $15,000. Tax result?","a":"Dividend $30,000; basis reduced to $0; capital gain $5,000.","work":["Dividend = current E&P $30,000 (deficit ignored)","Remaining $20,000 − basis $15,000 → basis to $0","Excess $5,000 = capital gain"]},"cites":[{"l":"IRC §316 Dividend defined","u":"https://www.law.cornell.edu/uscode/text/26/316"},{"l":"IRC §301 Distributions of property","u":"https://www.law.cornell.edu/uscode/text/26/301"},{"l":"IRC §311 Taxability of corporation on distribution","u":"https://www.law.cornell.edu/uscode/text/26/311"},{"l":"IRC §331 Gain or loss to shareholder in liquidation","u":"https://www.law.cornell.edu/uscode/text/26/331"},{"l":"IRC §332 Complete liquidations of subsidiaries","u":"https://www.law.cornell.edu/uscode/text/26/332"},{"l":"IRC §336 Gain or loss recognized by corporation","u":"https://www.law.cornell.edu/uscode/text/26/336"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":4,"rel":["REG-V-B-0037","REG-V-B-0041","REG-V-B-0045","REG-V-B-0050"]},{"id":"CARD-REG-V-C-01","area":"V","group":"C","topic":"S corporations — eligibility and election","title":"S corporation eligibility and election","rules":["Eligible corporation: domestic, up to 100 shareholders (family members count as one), one class of stock (IRC §1361)","Eligible shareholders: individual citizens or residents, estates, certain trusts; not partnerships, corporations, nonresident aliens","Voting differences allowed; different distribution or liquidation rights create a second class of stock","Ineligible: insurance companies under subchapter L, certain financial institutions; accumulated E&P does not bar election","Form 2553 by 15th day of 3rd month of tax year to be effective that year; all shareholders consent","Revocation needs consent of holders of more than half of all shares; re-election generally after 5 years"],"steps":["Corporation test → domestic, eligible type, one class of stock","Shareholder test → count (family as one), type, consents","File Form 2553 → within 2 months + 15 days of year start","Later disqualifying event → termination on that date"],"traps":["Voting differences treated as a second class of stock; only distribution or liquidation rights matter","Partnership or corporate shareholder accepted; only individuals, estates and certain trusts qualify"],"ex":{"q":"A new calendar-year corporation's tax year begins February 1, 2026. What is the last day to file Form 2553 for S status effective for 2026?","a":"April 15, 2026.","work":["Deadline = 2 months and 15 days after year start","February 1 + 2 months = April 1; + 15 days → April 15, 2026"]},"cites":[{"l":"IRC §1361 S corporation defined","u":"https://www.law.cornell.edu/uscode/text/26/1361"},{"l":"IRC §1362 Election; revocation; termination","u":"https://www.law.cornell.edu/uscode/text/26/1362"},{"l":"Instructions for Form 2553","u":"https://www.irs.gov/instructions/i2553"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":5,"rel":["REG-V-C-0001","REG-V-C-0004","REG-V-C-0008","REG-V-C-0044"]},{"id":"CARD-REG-V-C-02","area":"V","group":"C","topic":"S corporations — determination of ordinary business income (loss) and separately stated items","title":"S corporation income and separately stated items","rules":["Items pass through by shares per day owned; seller counts through the sale date (IRC §1377)","Separately stated: capital gains, §1231 gain, §179, charitable contributions, tax-exempt interest, portfolio income","Ordinary income deducts wages, COGS, regular depreciation; no DRD, NOL or federal income tax deduction","More-than-2% shareholder health premiums: W-2 box 14 information item; shareholder deducts on Schedule 1; excluded from FICA, Medicare and FUTA wages but included in income tax withholding wages (Pub. 15-B)","Reasonable compensation required before distributions; IRS may recharacterize distributions as wages","Distributive share taxed whether or not distributed"],"steps":["Compute ordinary income box 1 → remove separately stated items","Allocate per share per day","Separately stated items → own K-1 lines"],"traps":["Charity and capital gains netted into ordinary income; both are separately stated","Income allocated to year-end owners only; allocation is per share per day"],"ex":{"q":"A calendar-year S corporation has ordinary income $365,000 ($1,000 per day). A owns 40% of the shares from January 1 through March 31, 2026 and sells all to B on March 31. What ordinary income does A report?","a":"$36,000.","work":["A owns through sale date: January 1 to March 31 = 90 days","Income per day for A = 40% × $1,000 = $400","A reports 90 × $400 = $36,000"]},"cites":[{"l":"IRC §1366 Pass-thru of items","u":"https://www.law.cornell.edu/uscode/text/26/1366"},{"l":"IRC §1377 Definitions and special rules","u":"https://www.law.cornell.edu/uscode/text/26/1377"},{"l":"IRC §1363 Effect of election","u":"https://www.law.cornell.edu/uscode/text/26/1363"},{"l":"Instructions for Form 1120-S (2% shareholder health insurance)","u":"https://www.irs.gov/instructions/i1120s"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":6,"rel":["REG-V-C-0011","REG-V-C-0013","REG-V-C-0016","REG-V-C-0019"]},{"id":"CARD-REG-V-C-03","area":"V","group":"C","topic":"S corporations — basis of shareholder's interest","title":"S corporation shareholder basis","rules":["Stock basis + for income (ordinary, separately stated, tax-exempt), contributions","Basis − in order: distributions, nondeductible expenses, then losses (Reg. §1.1367-1(f))","Loss limited to stock basis then debt basis; excess suspended indefinitely (IRC §1366(d))","Net increase restores debt basis first, up to original amount, then stock basis (§1367(b)(2))","Corporate liabilities to outsiders do not add to basis, unlike partnerships","Repayment of debt with reduced basis → gain in proportion"],"steps":["Start basis + income items","− distributions → − nondeductible → − losses","Loss exceeds stock → reduce debt basis → remainder suspended","Later income → restore debt basis first"],"traps":["Outside corporate debt added to stock basis; that is a partnership rule","Income restores stock basis first; debt basis is restored first, up to its original amount"],"ex":{"q":"Shareholder stock basis $20,000; loan to S corporation $10,000. The corporation allocates a $45,000 loss. What loss is allowed, what is suspended, and what are the year-end bases?","a":"Allowed $30,000; suspended $15,000; stock basis $0; debt basis $0.","work":["Loss reduces stock basis first: $20,000 → $0","Excess $25,000 reduces debt basis: $10,000 → $0","Allowed = $20,000 + $10,000 = $30,000; suspended = $45,000 − $30,000 = $15,000"]},"cites":[{"l":"IRC §1367 Adjustments to basis of stock","u":"https://www.law.cornell.edu/uscode/text/26/1367"},{"l":"IRC §1366(d) Losses limited to basis","u":"https://www.law.cornell.edu/uscode/text/26/1366"},{"l":"26 CFR §1.1367-1 Adjustments to basis","u":"https://www.law.cornell.edu/cfr/text/26/1.1367-1"},{"l":"Instructions for Form 7203","u":"https://www.irs.gov/instructions/i7203"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":7,"rel":["REG-V-C-0027","REG-V-C-0030","REG-V-C-0033","REG-V-C-0036"]},{"id":"CARD-REG-V-C-04","area":"V","group":"C","topic":"S corporations — distributions and corporate-level taxes (supplement)","title":"S corporation distributions and corporate-level taxes","rules":["No C-corporation E&P: distribution reduces stock basis; excess over basis is capital gain (IRC §1368(b))","With C E&P: AAA distributed first, then E&P as dividend, then basis, then gain (§1368(c))","Built-in gains tax: 21% on net recognized built-in gain during 5-year recognition period (§1374)","Excess passive income tax: 21% of excess net passive income when passive receipts exceed 25% and C E&P exists (§1375)","Distribution of appreciated property → gain recognized and passed through (§311(b))","Reasonable compensation to shareholder-employees; C corporation profits face second layer of tax on distribution"],"steps":["Distribution → C E&P present? no → basis first","Yes → AAA, then E&P, then basis, then gain","Sale within recognition period → built-in gain limited to remaining NUBIG","Tax = 21% × recognized built-in gain"],"traps":["Built-in gains tax applied to sales after the 5-year period or to post-conversion appreciation; neither is taxed","Excess passive income tax computed on all passive income; only excess net passive income is taxed"],"ex":{"q":"A C corporation converted to S status on January 1, 2024, with net unrealized built-in gain of $200,000. In 2026 it sells an asset for a $250,000 gain (all built-in at conversion up to $200,000). Ignoring the taxable-income limit, built-in gains tax?","a":"$42,000.","work":["2026 is inside the 5-year recognition period (through 2028)","Recognized built-in gain = lesser of $250,000 gain or $200,000 NUBIG = $200,000","Tax = 21% × $200,000 = $42,000"]},"cites":[{"l":"IRC §1368 Distributions","u":"https://www.law.cornell.edu/uscode/text/26/1368"},{"l":"IRC §1374 Tax imposed on certain built-in gains","u":"https://www.law.cornell.edu/uscode/text/26/1374"},{"l":"IRC §1375 Tax on excess passive investment income","u":"https://www.law.cornell.edu/uscode/text/26/1375"},{"l":"IRC §311 Corporate distributions of property","u":"https://www.law.cornell.edu/uscode/text/26/311"},{"l":"IRC §3121 Wages (reasonable compensation)","u":"https://www.law.cornell.edu/uscode/text/26/3121"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":8,"rel":["REG-V-C-0038","REG-V-C-0039","REG-V-C-0041","REG-V-C-1002"]},{"id":"CARD-REG-V-D-01","area":"V","group":"D","topic":"Partnerships — determination of ordinary business income (loss) and separately stated items","title":"Partnership ordinary income and separately stated items","rules":["Ordinary income deducts wages, rent, guaranteed payments, regular depreciation; separately stated items go to K-1 (IRC §702, §703)","Separately stated: capital gains and losses, §1231, §179, charitable contributions, interest and dividend income","No deduction at partnership level for personal exemptions, income taxes, charitable gifts or net operating loss","Guaranteed payment for services: ordinary income to partner, deduction or capitalized cost to partnership (§707(c))","Form 1065 due March 15 (calendar year); automatic 6-month extension to September 15","Partner reports distributive share whether or not distributed"],"steps":["Revenue − ordinary expenses (incl. guaranteed payments) = ordinary income","Pull out separately stated items","Allocate by partnership agreement → K-1"],"traps":["Charitable contributions deducted in ordinary income; they are separately stated","Guaranteed payment ignored by the partnership; it is deducted there and ordinary income to the recipient"],"ex":{"q":"A partnership has revenue $500,000; wages $100,000, rent $40,000, guaranteed payments $60,000; charitable contributions $10,000 and §1231 gain $20,000. What are ordinary income and separately stated items?","a":"Ordinary income $300,000; separately stated: charity $10,000 and §1231 gain $20,000.","work":["Ordinary income = $500,000 − $100,000 − $40,000 − $60,000 = $300,000","Charity and §1231 gain are separately stated on K-1"]},"cites":[{"l":"IRC §702 Income and credits of partner","u":"https://www.law.cornell.edu/uscode/text/26/702"},{"l":"IRC §703 Partnership computations","u":"https://www.law.cornell.edu/uscode/text/26/703"},{"l":"IRC §707(c) Guaranteed payments","u":"https://www.law.cornell.edu/uscode/text/26/707"},{"l":"IRC §6072(b) Time for filing partnership returns","u":"https://www.law.cornell.edu/uscode/text/26/6072"},{"l":"Instructions for Form 1065","u":"https://www.irs.gov/instructions/i1065"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":9,"rel":["REG-V-D-0001","REG-V-D-0003","REG-V-D-0006","REG-V-D-0008"]},{"id":"CARD-REG-V-D-02","area":"V","group":"D","topic":"Partnerships — basis of partner's interest","title":"Partner basis in the partnership interest","rules":["Initial basis = cash contributed + adjusted basis of property contributed (IRC §722)","Basis + income, tax-exempt income, additional contributions, increase in share of liabilities (§705, §752(a))","Basis − distributions (cash + property basis), losses, nondeductible expenses, decrease in share of liabilities (§752(b))","Share of partnership liabilities is in basis, unlike an S corporation shareholder","Adjustment order: increases → distributions → losses; basis cannot fall below zero","Loss deductible only up to basis; excess carried forward (§704(d))"],"steps":["Start: contributions + liability share","+ income and tax-exempt income","− distributions, then − losses and nondeductible expenses","Floor at zero → excess loss suspended"],"traps":["Partnership debt ignored in basis; a partner's share of liabilities is included","Liability decrease ignored; it is a deemed cash distribution, taxed if above basis"],"ex":{"q":"A partner contributes $20,000 cash and property with basis $30,000. Her share of partnership liabilities is $50,000. She is allocated $15,000 of income and receives a $10,000 cash distribution. Ending basis?","a":"$105,000.","work":["Initial = $20,000 + $30,000 = $50,000; + liability share $50,000 = $100,000","+ income $15,000 = $115,000","− distribution $10,000 = $105,000"]},"cites":[{"l":"IRC §722 Basis of contributing partner's interest","u":"https://www.law.cornell.edu/uscode/text/26/722"},{"l":"IRC §705 Determination of basis","u":"https://www.law.cornell.edu/uscode/text/26/705"},{"l":"IRC §752 Liabilities","u":"https://www.law.cornell.edu/uscode/text/26/752"},{"l":"IRC §704(d) Limitation on allowance of losses","u":"https://www.law.cornell.edu/uscode/text/26/704"},{"l":"IRS Pub. 541 Partnerships","u":"https://www.irs.gov/publications/p541"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":10,"rel":["REG-V-D-0011","REG-V-D-0015","REG-V-D-0019","REG-V-D-0023"]},{"id":"CARD-REG-V-D-03","area":"V","group":"D","topic":"Partnerships — distributions, sale of an interest and basis adjustments (supplement)","title":"Partnership distributions and sale of an interest","rules":["Current distribution: gain only if cash exceeds outside basis; no partner loss (IRC §731(a)(1))","Distributed property takes partnership basis, limited to remaining outside basis (§732(a))","Liquidating distribution of only cash, receivables, inventory: loss = basis − cash − receivable and inventory basis (§731(a)(2))","Sale of interest: capital gain or loss, except unrealized receivables and inventory → ordinary (§741, §751)","Amount realized includes relief of partnership liabilities (§752(d))","§754 election → transferee basis adjustment = outside basis − share of inside basis (§743(b))"],"steps":["Cash first → reduce outside basis; excess → gain","Property → lesser of inside basis or remaining outside basis","Sale → amount realized incl. liability relief − outside basis","§751 assets → ordinary portion first"],"traps":["Gain recognized because property FMV exceeds basis; only cash above outside basis triggers gain","Loss recognized on a current distribution; loss arises only on liquidation for cash, receivables, inventory"],"ex":{"q":"A partner with outside basis $40,000 receives in a current distribution $15,000 cash and property (partnership basis $20,000, FMV $30,000). Gain, basis in property, and remaining outside basis?","a":"No gain; property basis $20,000; outside basis $5,000.","work":["Cash $15,000 → outside basis $40,000 − $15,000 = $25,000; no gain","Property basis = lesser of $20,000 or $25,000 = $20,000","Outside basis = $25,000 − $20,000 = $5,000"]},"cites":[{"l":"IRC §731 Distributions","u":"https://www.law.cornell.edu/uscode/text/26/731"},{"l":"IRC §732 Basis of distributed property","u":"https://www.law.cornell.edu/uscode/text/26/732"},{"l":"IRC §741 Sale of partnership interest","u":"https://www.law.cornell.edu/uscode/text/26/741"},{"l":"IRC §751 Unrealized receivables and inventory","u":"https://www.law.cornell.edu/uscode/text/26/751"},{"l":"IRC §743 Special adjustment to basis (§754)","u":"https://www.law.cornell.edu/uscode/text/26/743"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":11,"rel":["REG-V-D-0024","REG-V-D-0027","REG-V-D-0031","REG-V-D-0034"]},{"id":"CARD-REG-V-D-04","area":"V","group":"D","topic":"Partnerships — allocations, formation and tax year (supplement)","title":"Partnership allocations, contributions and tax year","rules":["Special allocation respected only with substantial economic effect (IRC §704(b))","Contributed property: built-in gain or loss allocated to contributor (§704(c)); traditional method has ceiling rule","Contribution for partnership interest: no gain or loss (§721(a)); partnership takes carryover basis (§723)","Tax year: majority-interest year (over 50% of profits and capital), then principal partners (§706(b))","Capital interest for services taxable at value; profits interest generally not taxed on receipt (Rev. Proc. 93-27, 2001-43)","Precontribution gain recognized by contributor on later sale, not shared"],"steps":["Book value vs tax basis of contributed property","Sale → built-in gain to contributor first","Remaining gain → shared by agreement"],"traps":["Built-in gain shared equally; it goes to the contributing partner first (§704(c))","Partnership year chosen freely; it follows partners owning over 50% of profits and capital"],"ex":{"q":"A contributes property (basis $30,000, FMV $50,000) to a two-equal-partner partnership. The property is sold for $60,000. How is the $30,000 gain allocated under the traditional method?","a":"A $25,000; B $5,000.","work":["Built-in gain = $50,000 − $30,000 = $20,000 → A","Remaining gain = $60,000 − $50,000 = $10,000 → shared 50/50 = $5,000 each","A = $20,000 + $5,000 = $25,000; B = $5,000"]},"cites":[{"l":"IRC §704 Partner's distributive share","u":"https://www.law.cornell.edu/uscode/text/26/704"},{"l":"IRC §721 Nonrecognition on contribution","u":"https://www.law.cornell.edu/uscode/text/26/721"},{"l":"IRC §706 Taxable years of partner and partnership","u":"https://www.law.cornell.edu/uscode/text/26/706"},{"l":"IRC §83 Property transferred in connection with services","u":"https://www.law.cornell.edu/uscode/text/26/83"},{"l":"IRS Rev. Proc. 2001-43 (profits interests; clarifies Rev. Proc. 93-27)","u":"https://www.irs.gov/pub/irs-drop/rp-01-43.pdf"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":12,"rel":["REG-V-D-0035","REG-V-D-0037","REG-V-D-0039","REG-V-D-1006"]},{"id":"CARD-REG-V-E-01","area":"V","group":"E","topic":"Limited liability companies","title":"LLC classification and elections","rules":["Default: single-member LLC disregarded; multi-member LLC taxed as partnership (Reg. §301.7701-3(b))","Form 8832 election to be taxed as a corporation; effective date up to 75 days before filing, 12 months after","Timely Form 2553 by an eligible LLC is also an election to be taxed as a corporation","After an election, another change is barred for 60 months","Single-member LLC is disregarded for income tax but a corporation for employment tax on its employees","Corporate classification adds a second layer of tax on distributed income"],"steps":["Members: 1 → disregarded; 2+ → partnership","Election? Form 8832 within 75-day look-back","Employment tax → LLC as employer even when disregarded"],"traps":["Classification changed again next year; a 60-month wait follows an election","Disregarded LLC ignored for employment tax; it is treated as a corporation for its employees' wages"],"ex":{"q":"An LLC (two members) files Form 8832 on June 1, 2026, electing corporate status. What is the earliest effective date?","a":"March 18, 2026.","work":["Effective date can be no more than 75 days before filing","June 1, 2026 − 75 days = March 18, 2026"]},"cites":[{"l":"26 CFR §301.7701-3 Classification of certain business entities","u":"https://www.law.cornell.edu/cfr/text/26/301.7701-3"},{"l":"26 CFR §301.7701-2 Business entities; definitions","u":"https://www.law.cornell.edu/cfr/text/26/301.7701-2"},{"l":"IRS Form 8832 page (instructions)","u":"https://www.irs.gov/forms-pubs/about-form-8832"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":13,"rel":["REG-V-E-0001","REG-V-E-0003","REG-V-E-1001","REG-V-E-1004"]},{"id":"CARD-REG-V-F-01","area":"V","group":"F","topic":"Tax-exempt organizations","title":"Exempt organization qualification","rules":["§501(c)(3): organized and operated exclusively for exempt purposes; no private inurement of net earnings","Insubstantial lobbying allowed; no political campaign activity","Business leagues, chambers of commerce: §501(c)(6); labor, agricultural, horticultural: §501(c)(5)","Public charity support test: gifts + grants ≥ one-third of total support (donor counted up to 2% in numerator)","Facts-and-circumstances test available if public support at least 10%","Application: Form 1023; contributions to §501(c)(3) generally deductible"],"steps":["Organizational test + operational test","Inurement? lobbying substantial? political activity? → exemption at risk","Public support ratio → ≥ 33⅓% public charity; 10% to 33⅓% facts-and-circumstances"],"traps":["Reasonable salaries and fees treated as inurement; only excess private benefit violates the rule","Large donor counted in full in the numerator; capped at 2% of total support (full in the denominator)"],"ex":{"q":"An organization has total support $1,000,000. Donor A gave $100,000; other public donors gave $260,000 in amounts under 2% each; the rest is investment income. What is its public support percentage?","a":"28%, below one-third but at least 10%.","work":["Donor A counted at 2% × $1,000,000 = $20,000","Numerator = $20,000 + $260,000 = $280,000","28% → fails one-third test; ≥10% allows facts-and-circumstances test"]},"cites":[{"l":"IRC §501 Exemption from tax","u":"https://www.law.cornell.edu/uscode/text/26/501"},{"l":"IRC §170(b)(1)(A)(vi) Public support","u":"https://www.law.cornell.edu/uscode/text/26/170"},{"l":"IRC §509 Private foundation defined","u":"https://www.law.cornell.edu/uscode/text/26/509"},{"l":"26 CFR §1.501(c)(3)-1","u":"https://www.law.cornell.edu/cfr/text/26/1.501(c)(3)-1"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":14,"rel":["REG-V-F-0001","REG-V-F-0002","REG-V-F-0003","REG-V-F-1002"]},{"id":"CARD-REG-V-F-02","area":"V","group":"F","topic":"Tax-exempt organizations — unrelated business income and filing (supplement)","title":"Unrelated business income and exempt organization filings","rules":["UBTI = gross unrelated business income − directly connected expenses − $1,000 specific deduction (IRC §512(b)(12))","Form 990-T required when gross unrelated business income is $1,000 or more","Excluded: dividends, interest, royalties, rents from real property, gains on property sales; debt-financed property included proportionately","Excluded: volunteer-run activity, sales of donated goods, convenience of members","Form 990-EZ: gross receipts under $200,000 and assets under $500,000; Form 990-N: receipts normally $50,000 or less","UBTI taxed at corporate rate for corporations, trust rates for trusts"],"steps":["Activity: trade or business + regularly carried on + not substantially related?","Remove excluded income","Gross UBI − direct expenses − $1,000"],"traps":["Volunteer sales and donated goods treated as unrelated; they are excluded (paid-staff sales of purchased goods are unrelated)","Dividends taxed as UBTI; they are excluded unless from debt-financed property"],"ex":{"q":"A charity has $30,000 gross income from an unrelated business with $12,000 of directly connected expenses. Compute UBTI and tax (corporate rate 21%).","a":"UBTI $17,000; tax $3,570.","work":["$30,000 − $12,000 − $1,000 = $17,000","21% × $17,000 = $3,570; Form 990-T required (gross ≥ $1,000)"]},"cites":[{"l":"IRC §512 Unrelated business taxable income","u":"https://www.law.cornell.edu/uscode/text/26/512"},{"l":"IRC §513 Unrelated trade or business","u":"https://www.law.cornell.edu/uscode/text/26/513"},{"l":"IRC §6033 Returns by exempt organizations","u":"https://www.law.cornell.edu/uscode/text/26/6033"},{"l":"Instructions for Form 990-T","u":"https://www.irs.gov/instructions/i990t"},{"l":"Instructions for Form 990-EZ","u":"https://www.irs.gov/instructions/i990ez"}],"from":"2026-01-01","asof":"2026-09-29","sk":"reg_area5_entities","node":15,"rel":["REG-V-F-0004","REG-V-F-0006","REG-V-F-1001","REG-V-F-1004"]},{"id":"CARD-REG-V-G-01","area":"V","group":"G","topic":"Trusts and estates (supplement; Blueprint placement unverified)","title":"Trusts and estates","rules":["Simple trust: distributes all income currently; no charitable gifts or principal distributions; exemption $300","Complex trust exemption $100; estate exemption $600 (IRC §642(b))","Distribution deduction and beneficiary inclusion limited to DNI (IRC §651, §652, §661, §662)","Estate may choose a fiscal year; most trusts must use the calendar year (IRC §644)","Compressed trust brackets 2026: 10% to $3,300; 24% to $11,700; 35% to $16,000; 37% above","Estate tax basic exclusion amount $15,000,000 for 2026 decedents [OBBBA; tested from 2026-07-01]"],"steps":["Fiduciary accounting income − fees → DNI","Simple trust → beneficiary taxed on income required to be distributed, up to DNI","Trust taxable income = income − distribution deduction − exemption"],"traps":["Principal gains carried out to a simple trust beneficiary; gains allocated to principal are taxed to the trust","Estate exemption set at $300 like a simple trust; a decedent's estate gets $600"],"ex":{"q":"A simple trust has $50,000 of interest income and $4,000 of trustee fees charged to income. It distributes all remaining income. What does the beneficiary report?","a":"$46,000.","work":["DNI = $50,000 − $4,000 = $46,000","Required distribution $46,000 ≤ DNI → beneficiary reports $46,000"]},"cites":[{"l":"IRC §643 Definitions (DNI)","u":"https://www.law.cornell.edu/uscode/text/26/643"},{"l":"IRC §651 Deduction for simple trusts","u":"https://www.law.cornell.edu/uscode/text/26/651"},{"l":"IRC §652 Inclusion in simple trusts","u":"https://www.law.cornell.edu/uscode/text/26/652"},{"l":"IRC §642(b) Personal exemption","u":"https://www.law.cornell.edu/uscode/text/26/642"},{"l":"IRC §644 Taxable year of trusts","u":"https://www.law.cornell.edu/uscode/text/26/644"},{"l":"Instructions for Form 1041 (estate fiscal year)","u":"https://www.irs.gov/instructions/i1041"},{"l":"IRC §2010 Unified credit (basic exclusion amount)","u":"https://www.law.cornell.edu/uscode/text/26/2010"},{"l":"IRS Rev. Proc. 2025-32 (2026 inflation adjustments)","u":"https://www.irs.gov/pub/irs-drop/rp-25-32.pdf"}],"from":"2026-07-01","asof":"2026-09-29","sk":"reg_area5_entities","node":16,"rel":["REG-V-G-0001","REG-V-G-0004","REG-V-G-1001","REG-V-G-1004"]}]};
